INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a1-m1-01', 'lesson-sequence-a1-m1', 1, 'sentence', 'Hello, I''m Ana.', 'Olá, sou a Ana.', '/həˈloʊ aɪm ˈænə/', 'Combine apresentação, perguntas e negativas com to be; peça repetição quando faltar compreensão. Reconheça respostas afirmativas e negativas em uma conversa curta.', '[]'::jsonb, '[{"surface":"Hello","pos":"interjection","ipa":"/həˈloʊ/","gloss":"olá"},{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"Ana","pos":"proper noun","ipa":"/ˈænə/","gloss":"Ana"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m1-02', 'lesson-sequence-a1-m1', 2, 'sentence', 'Are you a student?', 'Você é estudante?', '/ɑːr juː ə ˈstuːdənt/', 'Combine apresentação, perguntas e negativas com to be; peça repetição quando faltar compreensão. Reconheça respostas afirmativas e negativas em uma conversa curta.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"student","pos":"noun","ipa":"/ˈstuːdənt/","gloss":"estudante"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m1-03', 'lesson-sequence-a1-m1', 3, 'sentence', 'Yes, I am.', 'Sim, sou.', '/jɛs aɪ æm/', 'Combine apresentação, perguntas e negativas com to be; peça repetição quando faltar compreensão. Reconheça respostas afirmativas e negativas em uma conversa curta.', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m1-04', 'lesson-sequence-a1-m1', 4, 'sentence', 'Is your friend from Brazil?', 'Seu amigo é do Brasil?', '/ɪz jʊr frɛnd frʌm brəˈzɪl/', 'Combine apresentação, perguntas e negativas com to be; peça repetição quando faltar compreensão. Reconheça respostas afirmativas e negativas em uma conversa curta.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"friend","pos":"noun","ipa":"/frɛnd/","gloss":"amigo, amiga"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"Brazil","pos":"proper noun","ipa":"/brəˈzɪl/","gloss":"Brasil"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m1-05', 'lesson-sequence-a1-m1', 5, 'sentence', 'No, he isn''t.', 'Não, ele não é.', '/noʊ hiː ˈɪzənt/', 'Combine apresentação, perguntas e negativas com to be; peça repetição quando faltar compreensão. Reconheça respostas afirmativas e negativas em uma conversa curta.', '[]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"isn''t","pos":"auxiliary verb","ipa":"/ˈɪzənt/","gloss":"não é, não está"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m1-06', 'lesson-sequence-a1-m1', 6, 'sentence', 'Where are you from?', 'De onde você é?', '/wɛr ɑːr juː frʌm/', 'Combine apresentação, perguntas e negativas com to be; peça repetição quando faltar compreensão. Reconheça respostas afirmativas e negativas em uma conversa curta.', '[]'::jsonb, '[{"surface":"Where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m1-07', 'lesson-sequence-a1-m1', 7, 'sentence', 'I''m from Brazil.', 'Sou do Brasil.', '/aɪm frʌm brəˈzɪl/', 'Combine apresentação, perguntas e negativas com to be; peça repetição quando faltar compreensão. Reconheça respostas afirmativas e negativas em uma conversa curta.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"Brazil","pos":"proper noun","ipa":"/brəˈzɪl/","gloss":"Brasil"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m1-08', 'lesson-sequence-a1-m1', 8, 'sentence', 'Sorry, can you repeat that?', 'Desculpe, você pode repetir isso?', '/ˈsɑːri kæn juː rɪˈpiːt ðæt/', 'Combine apresentação, perguntas e negativas com to be; peça repetição quando faltar compreensão. Reconheça respostas afirmativas e negativas em uma conversa curta.', '[]'::jsonb, '[{"surface":"Sorry","pos":"adjective","ipa":"/ˈsɑːri/","gloss":"desculpa"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"repeat","pos":"verb","ipa":"/rɪˈpiːt/","gloss":"repetir"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a1-m2-01', 'lesson-sequence-a1-m2', 1, 'sentence', 'This is a pencil.', 'Isto é um lápis.', '/ðɪs ɪz ə ˈpɛnsəl/', 'Retome artigos, plurais, demonstrativos e there is/are ao identificar objetos. A primeira menção apresenta o objeto; a retomada usa the. Alterne singular e plural.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"pencil","pos":"noun","ipa":"/ˈpɛnsəl/","gloss":"lápis"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m2-02', 'lesson-sequence-a1-m2', 2, 'sentence', 'Is this your pencil?', 'Este é seu lápis?', '/ɪz ðɪs jʊr ˈpɛnsəl/', 'Retome artigos, plurais, demonstrativos e there is/are ao identificar objetos. A primeira menção apresenta o objeto; a retomada usa the. Alterne singular e plural.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"pencil","pos":"noun","ipa":"/ˈpɛnsəl/","gloss":"lápis"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m2-03', 'lesson-sequence-a1-m2', 3, 'sentence', 'Is that an apple?', 'Aquilo é uma maçã?', '/ɪz ðæt ən ˈæpəl/', 'Retome artigos, plurais, demonstrativos e there is/are ao identificar objetos. A primeira menção apresenta o objeto; a retomada usa the. Alterne singular e plural.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"apple","pos":"noun","ipa":"/ˈæpəl/","gloss":"maçã"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m2-04', 'lesson-sequence-a1-m2', 4, 'sentence', 'Yes, it is.', 'Sim, é.', '/jɛs ɪt ɪz/', 'Retome artigos, plurais, demonstrativos e there is/are ao identificar objetos. A primeira menção apresenta o objeto; a retomada usa the. Alterne singular e plural.', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m2-05', 'lesson-sequence-a1-m2', 5, 'sentence', 'These are books.', 'Estes são livros.', '/ðiːz ɑːr bʊks/', 'Retome artigos, plurais, demonstrativos e there is/are ao identificar objetos. A primeira menção apresenta o objeto; a retomada usa the. Alterne singular e plural.', '[]'::jsonb, '[{"surface":"These","pos":"determiner","ipa":"/ðiːz/","gloss":"estes, estas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"books","pos":"noun","ipa":"/bʊks/","gloss":"livros"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m2-06', 'lesson-sequence-a1-m2', 6, 'sentence', 'Those aren''t keys.', 'Aquelas não são chaves.', '/ðoʊz ɑːrnt kiːz/', 'Retome artigos, plurais, demonstrativos e there is/are ao identificar objetos. A primeira menção apresenta o objeto; a retomada usa the. Alterne singular e plural.', '[]'::jsonb, '[{"surface":"Those","pos":"determiner","ipa":"/ðoʊz/","gloss":"aqueles, essas"},{"surface":"aren''t","pos":"verb","ipa":"/ɑːrnt/","gloss":"não são, não estão (are not)"},{"surface":"keys","pos":"noun","ipa":"/kiːz/","gloss":"chaves"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m2-07', 'lesson-sequence-a1-m2', 7, 'sentence', 'There is a chair here.', 'Há uma cadeira aqui.', '/ðɛr ɪz ə tʃɛr hɪr/', 'Retome artigos, plurais, demonstrativos e there is/are ao identificar objetos. A primeira menção apresenta o objeto; a retomada usa the. Alterne singular e plural.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"chair","pos":"noun","ipa":"/tʃɛr/","gloss":"cadeira"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m2-08', 'lesson-sequence-a1-m2', 8, 'sentence', 'Are there chairs here?', 'Há cadeiras aqui?', '/ɑːr ðɛr tʃɛrz hɪr/', 'Retome artigos, plurais, demonstrativos e there is/are ao identificar objetos. A primeira menção apresenta o objeto; a retomada usa the. Alterne singular e plural.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"chairs","pos":"noun","ipa":"/tʃɛrz/","gloss":"cadeiras"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a1-m3-01', 'lesson-sequence-a1-m3', 1, 'sentence', 'This is my brother.', 'Este é meu irmão.', '/ðɪs ɪz maɪ ˈbrʌðər/', 'Combine possessivos, posse com ''s e descrição básica. Observe a diferença entre my e mine e entre uma descrição com be e a referência ao proprietário.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"brother","pos":"noun","ipa":"/ˈbrʌðər/","gloss":"irmão"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m3-02', 'lesson-sequence-a1-m3', 2, 'sentence', 'His name is Leo.', 'O nome dele é Leo.', '/hɪz neɪm ɪz ˈliːoʊ/', 'Combine possessivos, posse com ''s e descrição básica. Observe a diferença entre my e mine e entre uma descrição com be e a referência ao proprietário.', '[]'::jsonb, '[{"surface":"His","pos":"determiner","ipa":"/hɪz/","gloss":"dele"},{"surface":"name","pos":"noun","ipa":"/neɪm/","gloss":"nome"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"Leo","pos":"proper noun","ipa":"/ˈliːoʊ/","gloss":"Leo"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m3-03', 'lesson-sequence-a1-m3', 3, 'sentence', 'Is he tall?', 'Ele é alto?', '/ɪz hiː tɔːl/', 'Combine possessivos, posse com ''s e descrição básica. Observe a diferença entre my e mine e entre uma descrição com be e a referência ao proprietário.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"tall","pos":"adjective","ipa":"/tɔːl/","gloss":"alto"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m3-04', 'lesson-sequence-a1-m3', 4, 'sentence', 'No, he isn''t. He''s short.', 'Não, ele não é. Ele é baixo.', '/noʊ hiː ˈɪzənt hiːz ʃɔːrt/', 'Combine possessivos, posse com ''s e descrição básica. Observe a diferença entre my e mine e entre uma descrição com be e a referência ao proprietário.', '[]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"isn''t","pos":"auxiliary verb","ipa":"/ˈɪzənt/","gloss":"não é, não está"},{"surface":"He''s","pos":"pronoun","ipa":"/hiːz/","gloss":"ele é, ele está"},{"surface":"short","pos":"adjective","ipa":"/ʃɔːrt/","gloss":"curto"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m3-05', 'lesson-sequence-a1-m3', 5, 'sentence', 'This is my mother''s bag.', 'Esta é a bolsa da minha mãe.', '/ðɪs ɪz maɪ ˈmʌðərz bæɡ/', 'Combine possessivos, posse com ''s e descrição básica. Observe a diferença entre my e mine e entre uma descrição com be e a referência ao proprietário.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"mother''s","pos":"noun","ipa":"/ˈmʌðərz/","gloss":"da mãe"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m3-06', 'lesson-sequence-a1-m3', 6, 'sentence', 'Her bag is blue.', 'A bolsa dela é azul.', '/hɜːr bæɡ ɪz bluː/', 'Combine possessivos, posse com ''s e descrição básica. Observe a diferença entre my e mine e entre uma descrição com be e a referência ao proprietário.', '[]'::jsonb, '[{"surface":"Her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"blue","pos":"adjective","ipa":"/bluː/","gloss":"azul"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m3-07', 'lesson-sequence-a1-m3', 7, 'sentence', 'Is this phone yours?', 'Este telefone é seu?', '/ɪz ðɪs foʊn jʊrz/', 'Combine possessivos, posse com ''s e descrição básica. Observe a diferença entre my e mine e entre uma descrição com be e a referência ao proprietário.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"yours","pos":"pronoun","ipa":"/jʊrz/","gloss":"seu, o seu"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m3-08', 'lesson-sequence-a1-m3', 8, 'sentence', 'Yes, it''s mine.', 'Sim, é meu.', '/jɛs ɪts maɪn/', 'Combine possessivos, posse com ''s e descrição básica. Observe a diferença entre my e mine e entre uma descrição com be e a referência ao proprietário.', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"it''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"mine","pos":"pronoun","ipa":"/maɪn/","gloss":"meu, minha (sem substantivo)"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a1-m4-01', 'lesson-sequence-a1-m4', 1, 'sentence', 'What''s your phone number?', 'Qual é o seu número de telefone?', '/wʌts jʊr foʊn ˈnʌmbər/', 'Use os números já estudados para telefone, preço e horário. A revisão alterna perguntas e respostas e retoma dias da semana, sem introduzir cálculos ou estruturas avançadas.', '[]'::jsonb, '[{"surface":"What''s","pos":"pronoun","ipa":"/wʌts/","gloss":"qual é"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"number","pos":"noun","ipa":"/ˈnʌmbər/","gloss":"número"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m4-02', 'lesson-sequence-a1-m4', 2, 'sentence', 'It''s five, two, eight, one.', 'É cinco, dois, oito, um.', '/ɪts faɪv tuː eɪt wʌn/', 'Use os números já estudados para telefone, preço e horário. A revisão alterna perguntas e respostas e retoma dias da semana, sem introduzir cálculos ou estruturas avançadas.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"eight","pos":"numeral","ipa":"/eɪt/","gloss":"oito"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m4-03', 'lesson-sequence-a1-m4', 3, 'sentence', 'How much is this book?', 'Quanto custa este livro?', '/haʊ mʌtʃ ɪz ðɪs bʊk/', 'Use os números já estudados para telefone, preço e horário. A revisão alterna perguntas e respostas e retoma dias da semana, sem introduzir cálculos ou estruturas avançadas.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"book","pos":"verb","ipa":"/bʊk/","gloss":"reservar; livro"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m4-04', 'lesson-sequence-a1-m4', 4, 'sentence', 'It''s twelve dollars.', 'Custa doze dólares.', '/ɪts twɛlv ˈdɑːlərz/', 'Use os números já estudados para telefone, preço e horário. A revisão alterna perguntas e respostas e retoma dias da semana, sem introduzir cálculos ou estruturas avançadas.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"twelve","pos":"numeral","ipa":"/twɛlv/","gloss":"doze"},{"surface":"dollars","pos":"noun","ipa":"/ˈdɑːlərz/","gloss":"dólares"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m4-05', 'lesson-sequence-a1-m4', 5, 'sentence', 'What time is it?', 'Que horas são?', '/wʌt taɪm ɪz ɪt/', 'Use os números já estudados para telefone, preço e horário. A revisão alterna perguntas e respostas e retoma dias da semana, sem introduzir cálculos ou estruturas avançadas.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m4-06', 'lesson-sequence-a1-m4', 6, 'sentence', 'It''s half past seven.', 'São sete e meia.', '/ɪts hæf pæst ˈsɛvən/', 'Use os números já estudados para telefone, preço e horário. A revisão alterna perguntas e respostas e retoma dias da semana, sem introduzir cálculos ou estruturas avançadas.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"half","pos":"noun","ipa":"/hæf/","gloss":"metade, meio"},{"surface":"past","pos":"preposition","ipa":"/pæst/","gloss":"depois de (horas)"},{"surface":"seven","pos":"numeral","ipa":"/ˈsɛvən/","gloss":"sete"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m4-07', 'lesson-sequence-a1-m4', 7, 'sentence', 'Is the class on Monday?', 'A aula é na segunda-feira?', '/ɪz ðə klæs ɑːn ˈmʌndeɪ/', 'Use os números já estudados para telefone, preço e horário. A revisão alterna perguntas e respostas e retoma dias da semana, sem introduzir cálculos ou estruturas avançadas.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"class","pos":"noun","ipa":"/klæs/","gloss":"aula, turma"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Monday","pos":"proper noun","ipa":"/ˈmʌndeɪ/","gloss":"segunda-feira"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m4-08', 'lesson-sequence-a1-m4', 8, 'sentence', 'No, it''s on Tuesday.', 'Não, é na terça-feira.', '/noʊ ɪts ɑːn ˈtuːzdeɪ/', 'Use os números já estudados para telefone, preço e horário. A revisão alterna perguntas e respostas e retoma dias da semana, sem introduzir cálculos ou estruturas avançadas.', '[]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"it''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Tuesday","pos":"proper noun","ipa":"/ˈtuːzdeɪ/","gloss":"terça-feira"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a1-wh-01', 'lesson-sequence-a1-wh', 1, 'sentence', 'What do you study?', 'O que você estuda?', '/wʌt duː juː ˈstʌdi/', 'Escolha a palavra de pergunta pelo tipo de informação: what para coisa, where para lugar, when para momento, who para pessoa e how para modo. Com verbos comuns, use do/does e o verbo na base.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"study","pos":"verb","ipa":"/ˈstʌdi/","gloss":"estudar"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-wh-02', 'lesson-sequence-a1-wh', 2, 'sentence', 'Where does she work?', 'Onde ela trabalha?', '/wɛr dʌz ʃiː wɜːrk/', 'Escolha a palavra de pergunta pelo tipo de informação: what para coisa, where para lugar, when para momento, who para pessoa e how para modo. Com verbos comuns, use do/does e o verbo na base.', '[]'::jsonb, '[{"surface":"Where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-wh-03', 'lesson-sequence-a1-wh', 3, 'sentence', 'When do they start?', 'Quando eles começam?', '/wɛn duː ðeɪ stɑːrt/', 'Escolha a palavra de pergunta pelo tipo de informação: what para coisa, where para lugar, when para momento, who para pessoa e how para modo. Com verbos comuns, use do/does e o verbo na base.', '[]'::jsonb, '[{"surface":"When","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"start","pos":"verb","ipa":"/stɑːrt/","gloss":"começar"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-wh-04', 'lesson-sequence-a1-wh', 4, 'sentence', 'Who is that person?', 'Quem é aquela pessoa?', '/huː ɪz ðæt ˈpɜːrsən/', 'Escolha a palavra de pergunta pelo tipo de informação: what para coisa, where para lugar, when para momento, who para pessoa e how para modo. Com verbos comuns, use do/does e o verbo na base.', '[]'::jsonb, '[{"surface":"Who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"person","pos":"noun","ipa":"/ˈpɜːrsən/","gloss":"pessoa"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-wh-05', 'lesson-sequence-a1-wh', 5, 'sentence', 'How do you get to work?', 'Como você vai ao trabalho?', '/haʊ duː juː ɡɛt tuː wɜːrk/', 'Escolha a palavra de pergunta pelo tipo de informação: what para coisa, where para lugar, when para momento, who para pessoa e how para modo. Com verbos comuns, use do/does e o verbo na base.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-wh-06', 'lesson-sequence-a1-wh', 6, 'sentence', 'What does he want?', 'O que ele quer?', '/wʌt dʌz hiː wɑːnt/', 'Escolha a palavra de pergunta pelo tipo de informação: what para coisa, where para lugar, when para momento, who para pessoa e how para modo. Com verbos comuns, use do/does e o verbo na base.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"want","pos":"verb","ipa":"/wɑːnt/","gloss":"querer"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-wh-07', 'lesson-sequence-a1-wh', 7, 'sentence', 'Where are my glasses?', 'Onde estão os meus óculos?', '/wɛr ɑːr maɪ ˈɡlæsɪz/', 'Escolha a palavra de pergunta pelo tipo de informação: what para coisa, where para lugar, when para momento, who para pessoa e how para modo. Com verbos comuns, use do/does e o verbo na base.', '[]'::jsonb, '[{"surface":"Where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"glasses","pos":"noun","ipa":"/ˈɡlæsɪz/","gloss":"óculos"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-wh-08', 'lesson-sequence-a1-wh', 8, 'sentence', 'How old is your sister?', 'Quantos anos tem sua irmã?', '/haʊ oʊld ɪz jʊr ˈsɪstər/', 'Escolha a palavra de pergunta pelo tipo de informação: what para coisa, where para lugar, when para momento, who para pessoa e how para modo. Com verbos comuns, use do/does e o verbo na base.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"sister","pos":"noun","ipa":"/ˈsɪstər/","gloss":"irmã"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a1-m5-01', 'lesson-sequence-a1-m5', 1, 'sentence', 'Do you work every day?', 'Você trabalha todos os dias?', '/duː juː wɜːrk ˈɛvri deɪ/', 'Retome presente simples, do/does, have e frequência. Perguntas e negativas com does deixam o verbo na base. Use because para justificar e but para contrastar uma rotina.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m5-02', 'lesson-sequence-a1-m5', 2, 'sentence', 'No, I don''t work on Sundays.', 'Não, eu não trabalho aos domingos.', '/noʊ aɪ doʊnt wɜːrk ɑːn ˈsʌndeɪz/', 'Retome presente simples, do/does, have e frequência. Perguntas e negativas com does deixam o verbo na base. Use because para justificar e but para contrastar uma rotina.', '[]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Sundays","pos":"proper noun","ipa":"/ˈsʌndeɪz/","gloss":"domingos"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m5-03', 'lesson-sequence-a1-m5', 3, 'sentence', 'What time does she start?', 'A que horas ela começa?', '/wʌt taɪm dʌz ʃiː stɑːrt/', 'Retome presente simples, do/does, have e frequência. Perguntas e negativas com does deixam o verbo na base. Use because para justificar e but para contrastar uma rotina.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"start","pos":"verb","ipa":"/stɑːrt/","gloss":"começar"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m5-04', 'lesson-sequence-a1-m5', 4, 'sentence', 'She usually starts at eight.', 'Ela geralmente começa às oito.', '/ʃiː ˈjuːʒuəli stɑːrts æt eɪt/', 'Retome presente simples, do/does, have e frequência. Perguntas e negativas com does deixam o verbo na base. Use because para justificar e but para contrastar uma rotina.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"starts","pos":"verb","ipa":"/stɑːrts/","gloss":"começa"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"eight","pos":"numeral","ipa":"/eɪt/","gloss":"oito"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m5-05', 'lesson-sequence-a1-m5', 5, 'sentence', 'Does he have a car?', 'Ele tem carro?', '/dʌz hiː hæv ə kɑːr/', 'Retome presente simples, do/does, have e frequência. Perguntas e negativas com does deixam o verbo na base. Use because para justificar e but para contrastar uma rotina.', '[]'::jsonb, '[{"surface":"Does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m5-06', 'lesson-sequence-a1-m5', 6, 'sentence', 'No, he takes the bus.', 'Não, ele pega o ônibus.', '/noʊ hiː teɪks ðə bʌs/', 'Retome presente simples, do/does, have e frequência. Perguntas e negativas com does deixam o verbo na base. Use because para justificar e but para contrastar uma rotina.', '[]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"takes","pos":"verb","ipa":"/teɪks/","gloss":"pega, leva; decola"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m5-07', 'lesson-sequence-a1-m5', 7, 'sentence', 'I study at night because I work during the day.', 'Estudo à noite porque trabalho durante o dia.', '/aɪ ˈstʌdi æt naɪt bɪˈkɔːz aɪ wɜːrk ˈdʊrɪŋ ðə deɪ/', 'Retome presente simples, do/does, have e frequência. Perguntas e negativas com does deixam o verbo na base. Use because para justificar e but para contrastar uma rotina.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"study","pos":"verb","ipa":"/ˈstʌdi/","gloss":"estudar"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"},{"surface":"because","pos":"conjunction","ipa":"/bɪˈkɔːz/","gloss":"porque"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"during","pos":"preposition","ipa":"/ˈdʊrɪŋ/","gloss":"durante"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m5-08', 'lesson-sequence-a1-m5', 8, 'sentence', 'I like coffee, but I don''t drink it at night.', 'Gosto de café, mas não tomo café à noite.', '/aɪ laɪk ˈkɔːfi bʌt aɪ doʊnt drɪŋk ɪt æt naɪt/', 'Retome presente simples, do/does, have e frequência. Perguntas e negativas com does deixam o verbo na base. Use because para justificar e but para contrastar uma rotina.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"drink","pos":"verb","ipa":"/drɪŋk/","gloss":"beber"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a1-m6-01', 'lesson-sequence-a1-m6', 1, 'sentence', 'Where is the bus stop?', 'Onde fica o ponto de ônibus?', '/wɛr ɪz ðə bʌs stɑːp/', 'Retome there is/are e preposições de lugar para localizar pessoas e objetos. A resposta pode repetir o nome ou retomá-lo com it. Os pedidos de localização usam where.', '[]'::jsonb, '[{"surface":"Where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"},{"surface":"stop","pos":"verb","ipa":"/stɑːp/","gloss":"parar"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m6-02', 'lesson-sequence-a1-m6', 2, 'sentence', 'It''s near the school.', 'Fica perto da escola.', '/ɪts nɪr ðə skuːl/', 'Retome there is/are e preposições de lugar para localizar pessoas e objetos. A resposta pode repetir o nome ou retomá-lo com it. Os pedidos de localização usam where.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"near","pos":"preposition","ipa":"/nɪr/","gloss":"perto de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"school","pos":"noun","ipa":"/skuːl/","gloss":"escola"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m6-03', 'lesson-sequence-a1-m6', 3, 'sentence', 'Is there a store here?', 'Há uma loja aqui?', '/ɪz ðɛr ə stɔːr hɪr/', 'Retome there is/are e preposições de lugar para localizar pessoas e objetos. A resposta pode repetir o nome ou retomá-lo com it. Os pedidos de localização usam where.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"store","pos":"noun","ipa":"/stɔːr/","gloss":"loja, mercado"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m6-04', 'lesson-sequence-a1-m6', 4, 'sentence', 'Yes, it''s next to the bank.', 'Sim, fica ao lado do banco.', '/jɛs ɪts nɛkst tuː ðə bæŋk/', 'Retome there is/are e preposições de lugar para localizar pessoas e objetos. A resposta pode repetir o nome ou retomá-lo com it. Os pedidos de localização usam where.', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"it''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bank","pos":"noun","ipa":"/bæŋk/","gloss":"banco"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m6-05', 'lesson-sequence-a1-m6', 5, 'sentence', 'The keys are in my bag.', 'As chaves estão na minha bolsa.', '/ðə kiːz ɑːr ɪn maɪ bæɡ/', 'Retome there is/are e preposições de lugar para localizar pessoas e objetos. A resposta pode repetir o nome ou retomá-lo com it. Os pedidos de localização usam where.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"keys","pos":"noun","ipa":"/kiːz/","gloss":"chaves"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m6-06', 'lesson-sequence-a1-m6', 6, 'sentence', 'The bag is under the chair.', 'A bolsa está debaixo da cadeira.', '/ðə bæɡ ɪz ˈʌndər ðə tʃɛr/', 'Retome there is/are e preposições de lugar para localizar pessoas e objetos. A resposta pode repetir o nome ou retomá-lo com it. Os pedidos de localização usam where.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"under","pos":"preposition","ipa":"/ˈʌndər/","gloss":"no nome de, sob"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"chair","pos":"noun","ipa":"/tʃɛr/","gloss":"cadeira"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m6-07', 'lesson-sequence-a1-m6', 7, 'sentence', 'Are your friends at home?', 'Seus amigos estão em casa?', '/ɑːr jʊr frɛndz æt hoʊm/', 'Retome there is/are e preposições de lugar para localizar pessoas e objetos. A resposta pode repetir o nome ou retomá-lo com it. Os pedidos de localização usam where.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"friends","pos":"noun","ipa":"/frɛndz/","gloss":"amigos"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m6-08', 'lesson-sequence-a1-m6', 8, 'sentence', 'No, they''re at the park.', 'Não, eles estão no parque.', '/noʊ ðɛr æt ðə pɑːrk/', 'Retome there is/are e preposições de lugar para localizar pessoas e objetos. A resposta pode repetir o nome ou retomá-lo com it. Os pedidos de localização usam where.', '[]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"they''re","pos":"pronoun","ipa":"/ðɛr/","gloss":"eles são, eles estão"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"park","pos":"verb","ipa":"/pɑːrk/","gloss":"estacionar"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a1-m7-01', 'lesson-sequence-a1-m7', 1, 'sentence', 'Do you like tea?', 'Você gosta de chá?', '/duː juː laɪk tiː/', 'Combine gostos, some/any, can e imperativos em necessidades concretas. Can faz pedidos; please suaviza a instrução. Retome negativas sem acrescentar uma regra nova.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"tea","pos":"noun","ipa":"/tiː/","gloss":"chá"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m7-02', 'lesson-sequence-a1-m7', 2, 'sentence', 'Yes, but I don''t like coffee.', 'Sim, mas não gosto de café.', '/jɛs bʌt aɪ doʊnt laɪk ˈkɔːfi/', 'Combine gostos, some/any, can e imperativos em necessidades concretas. Can faz pedidos; please suaviza a instrução. Retome negativas sem acrescentar uma regra nova.', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m7-03', 'lesson-sequence-a1-m7', 3, 'sentence', 'Can I have some water, please?', 'Pode me dar um pouco de água, por favor?', '/kæn aɪ hæv sʌm ˈwɔːtər pliːz/', 'Combine gostos, some/any, can e imperativos em necessidades concretas. Can faz pedidos; please suaviza a instrução. Retome negativas sem acrescentar uma regra nova.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"water","pos":"noun","ipa":"/ˈwɔːtər/","gloss":"água"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m7-04', 'lesson-sequence-a1-m7', 4, 'sentence', 'We don''t have any cups.', 'Não temos copos.', '/wiː doʊnt hæv ˈɛni kʌps/', 'Combine gostos, some/any, can e imperativos em necessidades concretas. Can faz pedidos; please suaviza a instrução. Retome negativas sem acrescentar uma regra nova.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"cups","pos":"noun","ipa":"/kʌps/","gloss":"xícaras"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m7-05', 'lesson-sequence-a1-m7', 5, 'sentence', 'Can you help me?', 'Você pode me ajudar?', '/kæn juː hɛlp miː/', 'Combine gostos, some/any, can e imperativos em necessidades concretas. Can faz pedidos; please suaviza a instrução. Retome negativas sem acrescentar uma regra nova.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m7-06', 'lesson-sequence-a1-m7', 6, 'sentence', 'Open the door, please.', 'Abra a porta, por favor.', '/ˈoʊpən ðə dɔːr pliːz/', 'Combine gostos, some/any, can e imperativos em necessidades concretas. Can faz pedidos; please suaviza a instrução. Retome negativas sem acrescentar uma regra nova.', '[]'::jsonb, '[{"surface":"Open","pos":"verb","ipa":"/ˈoʊpən/","gloss":"abrir"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"door","pos":"noun","ipa":"/dɔːr/","gloss":"porta"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m7-07', 'lesson-sequence-a1-m7', 7, 'sentence', 'Don''t touch that.', 'Não toque nisso.', '/doʊnt tʌtʃ ðæt/', 'Combine gostos, some/any, can e imperativos em necessidades concretas. Can faz pedidos; please suaviza a instrução. Retome negativas sem acrescentar uma regra nova.', '[]'::jsonb, '[{"surface":"Don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"touch","pos":"verb","ipa":"/tʌtʃ/","gloss":"tocar, encostar"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m7-08', 'lesson-sequence-a1-m7', 8, 'sentence', 'I can cook, but I can''t drive.', 'Sei cozinhar, mas não sei dirigir.', '/aɪ kæn kʊk bʌt aɪ kænt draɪv/', 'Combine gostos, some/any, can e imperativos em necessidades concretas. Can faz pedidos; please suaviza a instrução. Retome negativas sem acrescentar uma regra nova.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"cook","pos":"noun","ipa":"/kʊk/","gloss":"cozinheiro"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"drive","pos":"verb","ipa":"/draɪv/","gloss":"dirigir"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a1-m8-01', 'lesson-sequence-a1-m8', 1, 'sentence', 'My name is Pedro, and I''m a student.', 'Meu nome é Pedro e sou estudante.', '/maɪ neɪm ɪz ˈpeɪdroʊ ænd aɪm ə ˈstuːdənt/', 'Retome as estruturas do A1 em situações familiares. A rotina usa presente simples; a ação acontecendo agora usa be + -ing. Esta revisão controla as respostas e não comprova produção espontânea.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"name","pos":"noun","ipa":"/neɪm/","gloss":"nome"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"Pedro","pos":"proper noun","ipa":"/ˈpeɪdroʊ/","gloss":"Pedro"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"student","pos":"noun","ipa":"/ˈstuːdənt/","gloss":"estudante"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m8-02', 'lesson-sequence-a1-m8', 2, 'sentence', 'I live near the school.', 'Moro perto da escola.', '/aɪ lɪv nɪr ðə skuːl/', 'Retome as estruturas do A1 em situações familiares. A rotina usa presente simples; a ação acontecendo agora usa be + -ing. Esta revisão controla as respostas e não comprova produção espontânea.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"live","pos":"verb","ipa":"/lɪv/","gloss":"morar, viver"},{"surface":"near","pos":"preposition","ipa":"/nɪr/","gloss":"perto de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"school","pos":"noun","ipa":"/skuːl/","gloss":"escola"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m8-03', 'lesson-sequence-a1-m8', 3, 'sentence', 'I have two brothers.', 'Tenho dois irmãos.', '/aɪ hæv tuː ˈbrʌðərz/', 'Retome as estruturas do A1 em situações familiares. A rotina usa presente simples; a ação acontecendo agora usa be + -ing. Esta revisão controla as respostas e não comprova produção espontânea.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"brothers","pos":"noun","ipa":"/ˈbrʌðərz/","gloss":"irmãos"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m8-04', 'lesson-sequence-a1-m8', 4, 'sentence', 'I usually walk to class.', 'Geralmente vou a pé para a aula.', '/aɪ ˈjuːʒuəli wɔːk tuː klæs/', 'Retome as estruturas do A1 em situações familiares. A rotina usa presente simples; a ação acontecendo agora usa be + -ing. Esta revisão controla as respostas e não comprova produção espontânea.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"walk","pos":"noun","ipa":"/wɔːk/","gloss":"caminhada; andar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"class","pos":"noun","ipa":"/klæs/","gloss":"aula, turma"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m8-05', 'lesson-sequence-a1-m8', 5, 'sentence', 'Today I''m studying at home.', 'Hoje estou estudando em casa.', '/təˈdeɪ aɪm ˈstʌdiɪŋ æt hoʊm/', 'Retome as estruturas do A1 em situações familiares. A rotina usa presente simples; a ação acontecendo agora usa be + -ing. Esta revisão controla as respostas e não comprova produção espontânea.', '[]'::jsonb, '[{"surface":"Today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"},{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"studying","pos":"verb","ipa":"/ˈstʌdiɪŋ/","gloss":"estudando"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m8-06', 'lesson-sequence-a1-m8', 6, 'sentence', 'My brother isn''t working now.', 'Meu irmão não está trabalhando agora.', '/maɪ ˈbrʌðər ˈɪzənt ˈwɜːrkɪŋ naʊ/', 'Retome as estruturas do A1 em situações familiares. A rotina usa presente simples; a ação acontecendo agora usa be + -ing. Esta revisão controla as respostas e não comprova produção espontânea.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"brother","pos":"noun","ipa":"/ˈbrʌðər/","gloss":"irmão"},{"surface":"isn''t","pos":"auxiliary verb","ipa":"/ˈɪzənt/","gloss":"não é, não está"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m8-07', 'lesson-sequence-a1-m8', 7, 'sentence', 'Are you listening to me?', 'Você está me ouvindo?', '/ɑːr juː ˈlɪsənɪŋ tuː miː/', 'Retome as estruturas do A1 em situações familiares. A rotina usa presente simples; a ação acontecendo agora usa be + -ing. Esta revisão controla as respostas e não comprova produção espontânea.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"listening","pos":"verb","ipa":"/ˈlɪsənɪŋ/","gloss":"ouvindo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a1-m8-08', 'lesson-sequence-a1-m8', 8, 'sentence', 'Yes, I am. Please speak slowly.', 'Sim, estou. Por favor, fale devagar.', '/jɛs aɪ æm pliːz spiːk ˈsloʊli/', 'Retome as estruturas do A1 em situações familiares. A rotina usa presente simples; a ação acontecendo agora usa be + -ing. Esta revisão controla as respostas e não comprova produção espontânea.', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"speak","pos":"verb","ipa":"/spiːk/","gloss":"falar"},{"surface":"slowly","pos":"adverb","ipa":"/ˈsloʊli/","gloss":"devagar"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a2-m1-01', 'lesson-sequence-a2-m1', 1, 'sentence', 'I usually work at the office.', 'Geralmente trabalho no escritório.', '/aɪ ˈjuːʒuəli wɜːrk æt ðə ˈɔːfɪs/', 'Contraste o que acontece habitualmente com uma ação atual ou temporária. As expressões every day, today e this week orientam a escolha; perguntas e negativas retomam ambos os padrões.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"office","pos":"noun","ipa":"/ˈɔːfɪs/","gloss":"escritório, balcão"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m1-02', 'lesson-sequence-a2-m1', 2, 'sentence', 'This week I''m working at home.', 'Esta semana estou trabalhando em casa.', '/ðɪs wiːk aɪm ˈwɜːrkɪŋ æt hoʊm/', 'Contraste o que acontece habitualmente com uma ação atual ou temporária. As expressões every day, today e this week orientam a escolha; perguntas e negativas retomam ambos os padrões.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"},{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m1-03', 'lesson-sequence-a2-m1', 3, 'sentence', 'Does she study every evening?', 'Ela estuda todas as noites?', '/dʌz ʃiː ˈstʌdi ˈɛvri ˈiːvnɪŋ/', 'Contraste o que acontece habitualmente com uma ação atual ou temporária. As expressões every day, today e this week orientam a escolha; perguntas e negativas retomam ambos os padrões.', '[]'::jsonb, '[{"surface":"Does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"study","pos":"verb","ipa":"/ˈstʌdi/","gloss":"estudar"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"evening","pos":"noun","ipa":"/ˈiːvnɪŋ/","gloss":"noite (início), fim de tarde"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m1-04', 'lesson-sequence-a2-m1', 4, 'sentence', 'No, she doesn''t study on Fridays.', 'Não, ela não estuda às sextas-feiras.', '/noʊ ʃiː ˈdʌzənt ˈstʌdi ɑːn ˈfraɪdeɪz/', 'Contraste o que acontece habitualmente com uma ação atual ou temporária. As expressões every day, today e this week orientam a escolha; perguntas e negativas retomam ambos os padrões.', '[]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"doesn''t","pos":"verb","ipa":"/ˈdʌzənt/","gloss":"não (does not)"},{"surface":"study","pos":"verb","ipa":"/ˈstʌdi/","gloss":"estudar"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Fridays","pos":"proper noun","ipa":"/ˈfraɪdeɪz/","gloss":"sextas-feiras"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m1-05', 'lesson-sequence-a2-m1', 5, 'sentence', 'What are the children doing?', 'O que as crianças estão fazendo?', '/wʌt ɑːr ðə ˈtʃɪldrən ˈduːɪŋ/', 'Contraste o que acontece habitualmente com uma ação atual ou temporária. As expressões every day, today e this week orientam a escolha; perguntas e negativas retomam ambos os padrões.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"children","pos":"noun","ipa":"/ˈtʃɪldrən/","gloss":"crianças, filhos"},{"surface":"doing","pos":"verb","ipa":"/ˈduːɪŋ/","gloss":"fazendo, fazer"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m1-06', 'lesson-sequence-a2-m1', 6, 'sentence', 'They''re playing in the living room.', 'Estão brincando na sala.', '/ðɛr ˈpleɪɪŋ ɪn ðə ˈlɪvɪŋ ruːm/', 'Contraste o que acontece habitualmente com uma ação atual ou temporária. As expressões every day, today e this week orientam a escolha; perguntas e negativas retomam ambos os padrões.', '[]'::jsonb, '[{"surface":"They''re","pos":"pronoun","ipa":"/ðɛr/","gloss":"eles são, eles estão"},{"surface":"playing","pos":"verb","ipa":"/ˈpleɪɪŋ/","gloss":"jogando, brincando"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"living","pos":"adjective","ipa":"/ˈlɪvɪŋ/","gloss":"de estar"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m1-07', 'lesson-sequence-a2-m1', 7, 'sentence', 'I''m not using the computer now.', 'Não estou usando o computador agora.', '/aɪm nɑːt ˈjuːzɪŋ ðə kəmˈpjuːtər naʊ/', 'Contraste o que acontece habitualmente com uma ação atual ou temporária. As expressões every day, today e this week orientam a escolha; perguntas e negativas retomam ambos os padrões.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"using","pos":"verb","ipa":"/ˈjuːzɪŋ/","gloss":"usando"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"computer","pos":"noun","ipa":"/kəmˈpjuːtər/","gloss":"computador"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m1-08', 'lesson-sequence-a2-m1', 8, 'sentence', 'Do you need it for your homework?', 'Você precisa dele para a lição de casa?', '/duː juː niːd ɪt fɔːr jʊr ˈhoʊmwɜːrk/', 'Contraste o que acontece habitualmente com uma ação atual ou temporária. As expressões every day, today e this week orientam a escolha; perguntas e negativas retomam ambos os padrões.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"homework","pos":"noun","ipa":"/ˈhoʊmwɜːrk/","gloss":"lição de casa"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a2-m2-01', 'lesson-sequence-a2-m2', 1, 'sentence', 'Were you at home yesterday?', 'Você estava em casa ontem?', '/wɜːr juː æt hoʊm ˈjɛstərdeɪ/', 'Retome was/were, passado simples e a relação entre ação em andamento e acontecimento. Did/didn''t deixam o verbo principal na base; organize a pequena narrativa com yesterday, when e then.', '[]'::jsonb, '[{"surface":"Were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"yesterday","pos":"adverb","ipa":"/ˈjɛstərdeɪ/","gloss":"ontem"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m2-02', 'lesson-sequence-a2-m2', 2, 'sentence', 'No, I was at work.', 'Não, eu estava no trabalho.', '/noʊ aɪ wɑːz æt wɜːrk/', 'Retome was/were, passado simples e a relação entre ação em andamento e acontecimento. Did/didn''t deixam o verbo principal na base; organize a pequena narrativa com yesterday, when e then.', '[]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m2-03', 'lesson-sequence-a2-m2', 3, 'sentence', 'What did you do after work?', 'O que você fez depois do trabalho?', '/wʌt dɪd juː duː ˈæftər wɜːrk/', 'Retome was/were, passado simples e a relação entre ação em andamento e acontecimento. Did/didn''t deixam o verbo principal na base; organize a pequena narrativa com yesterday, when e then.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m2-04', 'lesson-sequence-a2-m2', 4, 'sentence', 'I called my sister and cooked dinner.', 'Liguei para minha irmã e preparei o jantar.', '/aɪ kɔːld maɪ ˈsɪstər ænd kʊkt ˈdɪnər/', 'Retome was/were, passado simples e a relação entre ação em andamento e acontecimento. Did/didn''t deixam o verbo principal na base; organize a pequena narrativa com yesterday, when e then.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"called","pos":"verb","ipa":"/kɔːld/","gloss":"ligou, chamou"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"sister","pos":"noun","ipa":"/ˈsɪstər/","gloss":"irmã"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"cooked","pos":"verb","ipa":"/kʊkt/","gloss":"cozinhou; preparado"},{"surface":"dinner","pos":"noun","ipa":"/ˈdɪnər/","gloss":"jantar"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m2-05', 'lesson-sequence-a2-m2', 5, 'sentence', 'She didn''t answer the phone.', 'Ela não atendeu o telefone.', '/ʃiː ˈdɪdənt ˈænsər ðə foʊn/', 'Retome was/were, passado simples e a relação entre ação em andamento e acontecimento. Did/didn''t deixam o verbo principal na base; organize a pequena narrativa com yesterday, when e then.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"answer","pos":"noun","ipa":"/ˈænsər/","gloss":"resposta"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m2-06', 'lesson-sequence-a2-m2', 6, 'sentence', 'She was driving when I called.', 'Ela estava dirigindo quando liguei.', '/ʃiː wɑːz ˈdraɪvɪŋ wɛn aɪ kɔːld/', 'Retome was/were, passado simples e a relação entre ação em andamento e acontecimento. Did/didn''t deixam o verbo principal na base; organize a pequena narrativa com yesterday, when e then.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"driving","pos":"verb","ipa":"/ˈdraɪvɪŋ/","gloss":"dirigindo"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"called","pos":"verb","ipa":"/kɔːld/","gloss":"ligou, chamou"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m2-07', 'lesson-sequence-a2-m2', 7, 'sentence', 'Did she call you later?', 'Ela ligou para você depois?', '/dɪd ʃiː kɔːl juː ˈleɪtər/', 'Retome was/were, passado simples e a relação entre ação em andamento e acontecimento. Did/didn''t deixam o verbo principal na base; organize a pequena narrativa com yesterday, when e then.', '[]'::jsonb, '[{"surface":"Did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"later","pos":"adverb","ipa":"/ˈleɪtər/","gloss":"mais tarde"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m2-08', 'lesson-sequence-a2-m2', 8, 'sentence', 'Yes, and then we talked for a few minutes.', 'Sim, e então conversamos por alguns minutos.', '/jɛs ænd ðɛn wiː tɔːkt fɔːr ə fjuː ˈmɪnɪts/', 'Retome was/were, passado simples e a relação entre ação em andamento e acontecimento. Did/didn''t deixam o verbo principal na base; organize a pequena narrativa com yesterday, when e then.', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"then","pos":"adverb","ipa":"/ðɛn/","gloss":"então, depois"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"talked","pos":"verb","ipa":"/tɔːkt/","gloss":"conversou"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"few","pos":"determiner","ipa":"/fjuː/","gloss":"poucos"},{"surface":"minutes","pos":"noun","ipa":"/ˈmɪnɪts/","gloss":"minutos"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a2-m3-01', 'lesson-sequence-a2-m3', 1, 'sentence', 'Which bag do you prefer?', 'Qual bolsa você prefere?', '/wɪtʃ bæɡ duː juː prɪˈfɜːr/', 'Retome descrição, comparativos e superlativos para escolher entre opções. A revisão inclui formas regulares e irregulares; os motivos usam because e a comparação usa than.', '[]'::jsonb, '[{"surface":"Which","pos":"determiner","ipa":"/wɪtʃ/","gloss":"qual"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"prefer","pos":"verb","ipa":"/prɪˈfɜːr/","gloss":"preferir"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m3-02', 'lesson-sequence-a2-m3', 2, 'sentence', 'The blue one is cheaper than the red one.', 'A azul é mais barata que a vermelha.', '/ðə bluː wʌn ɪz ˈtʃiːpər ðæn ðə rɛd wʌn/', 'Retome descrição, comparativos e superlativos para escolher entre opções. A revisão inclui formas regulares e irregulares; os motivos usam because e a comparação usa than.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"blue","pos":"adjective","ipa":"/bluː/","gloss":"azul"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"cheaper","pos":"adjective","ipa":"/ˈtʃiːpər/","gloss":"mais barato"},{"surface":"than","pos":"conjunction","ipa":"/ðæn/","gloss":"do que"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"red","pos":"adjective","ipa":"/rɛd/","gloss":"vermelho"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m3-03', 'lesson-sequence-a2-m3', 3, 'sentence', 'Is it comfortable?', 'Ela é confortável?', '/ɪz ɪt ˈkʌmftərbəl/', 'Retome descrição, comparativos e superlativos para escolher entre opções. A revisão inclui formas regulares e irregulares; os motivos usam because e a comparação usa than.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"comfortable","pos":"adjective","ipa":"/ˈkʌmftərbəl/","gloss":"confortável"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m3-04', 'lesson-sequence-a2-m3', 4, 'sentence', 'Yes, it''s bigger than my old bag.', 'Sim, é maior que minha bolsa antiga.', '/jɛs ɪts ˈbɪɡər ðæn maɪ oʊld bæɡ/', 'Retome descrição, comparativos e superlativos para escolher entre opções. A revisão inclui formas regulares e irregulares; os motivos usam because e a comparação usa than.', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"it''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"bigger","pos":"adjective","ipa":"/ˈbɪɡər/","gloss":"maior"},{"surface":"than","pos":"conjunction","ipa":"/ðæn/","gloss":"do que"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m3-05', 'lesson-sequence-a2-m3', 5, 'sentence', 'This is the most comfortable chair.', 'Esta é a cadeira mais confortável.', '/ðɪs ɪz ðə moʊst ˈkʌmftərbəl tʃɛr/', 'Retome descrição, comparativos e superlativos para escolher entre opções. A revisão inclui formas regulares e irregulares; os motivos usam because e a comparação usa than.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"most","pos":"determiner","ipa":"/moʊst/","gloss":"o máximo, a maioria"},{"surface":"comfortable","pos":"adjective","ipa":"/ˈkʌmftərbəl/","gloss":"confortável"},{"surface":"chair","pos":"noun","ipa":"/tʃɛr/","gloss":"cadeira"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m3-06', 'lesson-sequence-a2-m3', 6, 'sentence', 'That one is less expensive.', 'Aquela é menos cara.', '/ðæt wʌn ɪz lɛs ɪkˈspɛnsɪv/', 'Retome descrição, comparativos e superlativos para escolher entre opções. A revisão inclui formas regulares e irregulares; os motivos usam because e a comparação usa than.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"less","pos":"determiner","ipa":"/lɛs/","gloss":"menos"},{"surface":"expensive","pos":"adjective","ipa":"/ɪkˈspɛnsɪv/","gloss":"caro"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m3-07', 'lesson-sequence-a2-m3', 7, 'sentence', 'The train is better because it''s faster.', 'O trem é melhor porque é mais rápido.', '/ðə treɪn ɪz ˈbɛtər bɪˈkɔːz ɪts ˈfæstər/', 'Retome descrição, comparativos e superlativos para escolher entre opções. A revisão inclui formas regulares e irregulares; os motivos usam because e a comparação usa than.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"better","pos":"adjective","ipa":"/ˈbɛtər/","gloss":"melhor"},{"surface":"because","pos":"conjunction","ipa":"/bɪˈkɔːz/","gloss":"porque"},{"surface":"it''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"faster","pos":"adjective","ipa":"/ˈfæstər/","gloss":"mais rápido"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m3-08', 'lesson-sequence-a2-m3', 8, 'sentence', 'What''s the best option for us?', 'Qual é a melhor opção para nós?', '/wʌts ðə bɛst ˈɑːpʃən fɔːr ʌs/', 'Retome descrição, comparativos e superlativos para escolher entre opções. A revisão inclui formas regulares e irregulares; os motivos usam because e a comparação usa than.', '[]'::jsonb, '[{"surface":"What''s","pos":"pronoun","ipa":"/wʌts/","gloss":"qual é"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"best","pos":"adjective","ipa":"/bɛst/","gloss":"melhor"},{"surface":"option","pos":"noun","ipa":"/ˈɑːpʃən/","gloss":"opção"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a2-m4-01', 'lesson-sequence-a2-m4', 1, 'sentence', 'How many tomatoes do we need?', 'De quantos tomates precisamos?', '/haʊ ˈmɛni təˈmeɪtoʊz duː wiː niːd/', 'Retome contáveis/incontáveis, much/many, some/any e enough numa compra. A revisão exige alternar perguntas e respostas e distinguir quantidade de objetos e de substâncias.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"many","pos":"determiner","ipa":"/ˈmɛni/","gloss":"muitos (how many)"},{"surface":"tomatoes","pos":"noun","ipa":"/təˈmeɪtoʊz/","gloss":"tomates"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m4-02', 'lesson-sequence-a2-m4', 2, 'sentence', 'We need a few tomatoes and some rice.', 'Precisamos de alguns tomates e um pouco de arroz.', '/wiː niːd ə fjuː təˈmeɪtoʊz ænd sʌm raɪs/', 'Retome contáveis/incontáveis, much/many, some/any e enough numa compra. A revisão exige alternar perguntas e respostas e distinguir quantidade de objetos e de substâncias.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"few","pos":"determiner","ipa":"/fjuː/","gloss":"poucos"},{"surface":"tomatoes","pos":"noun","ipa":"/təˈmeɪtoʊz/","gloss":"tomates"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"rice","pos":"noun","ipa":"/raɪs/","gloss":"arroz"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m4-03', 'lesson-sequence-a2-m4', 3, 'sentence', 'Is there enough milk?', 'Há leite suficiente?', '/ɪz ðɛr ɪˈnʌf mɪlk/', 'Retome contáveis/incontáveis, much/many, some/any e enough numa compra. A revisão exige alternar perguntas e respostas e distinguir quantidade de objetos e de substâncias.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"enough","pos":"adverb","ipa":"/ɪˈnʌf/","gloss":"o bastante"},{"surface":"milk","pos":"noun","ipa":"/mɪlk/","gloss":"leite"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m4-04', 'lesson-sequence-a2-m4', 4, 'sentence', 'No, we don''t have much milk.', 'Não, não temos muito leite.', '/noʊ wiː doʊnt hæv mʌtʃ mɪlk/', 'Retome contáveis/incontáveis, much/many, some/any e enough numa compra. A revisão exige alternar perguntas e respostas e distinguir quantidade de objetos e de substâncias.', '[]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"milk","pos":"noun","ipa":"/mɪlk/","gloss":"leite"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m4-05', 'lesson-sequence-a2-m4', 5, 'sentence', 'Do we have any bread?', 'Temos pão?', '/duː wiː hæv ˈɛni brɛd/', 'Retome contáveis/incontáveis, much/many, some/any e enough numa compra. A revisão exige alternar perguntas e respostas e distinguir quantidade de objetos e de substâncias.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"bread","pos":"noun","ipa":"/brɛd/","gloss":"pão"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m4-06', 'lesson-sequence-a2-m4', 6, 'sentence', 'Yes, but we need a little butter.', 'Sim, mas precisamos de um pouco de manteiga.', '/jɛs bʌt wiː niːd ə ˈlɪtəl ˈbʌtər/', 'Retome contáveis/incontáveis, much/many, some/any e enough numa compra. A revisão exige alternar perguntas e respostas e distinguir quantidade de objetos e de substâncias.', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"little","pos":"adjective","ipa":"/ˈlɪtəl/","gloss":"pouco, pequeno"},{"surface":"butter","pos":"noun","ipa":"/ˈbʌtər/","gloss":"manteiga"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m4-07', 'lesson-sequence-a2-m4', 7, 'sentence', 'How much does it cost?', 'Quanto custa?', '/haʊ mʌtʃ dʌz ɪt kɔːst/', 'Retome contáveis/incontáveis, much/many, some/any e enough numa compra. A revisão exige alternar perguntas e respostas e distinguir quantidade de objetos e de substâncias.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"cost","pos":"verb","ipa":"/kɔːst/","gloss":"custar"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m4-08', 'lesson-sequence-a2-m4', 8, 'sentence', 'It''s too expensive. Let''s buy this one.', 'É caro demais. Vamos comprar este.', '/ɪts tuː ɪkˈspɛnsɪv lɛts baɪ ðɪs wʌn/', 'Retome contáveis/incontáveis, much/many, some/any e enough numa compra. A revisão exige alternar perguntas e respostas e distinguir quantidade de objetos e de substâncias.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"},{"surface":"expensive","pos":"adjective","ipa":"/ɪkˈspɛnsɪv/","gloss":"caro"},{"surface":"Let''s","pos":"verb","ipa":"/lɛts/","gloss":"vamos"},{"surface":"buy","pos":"verb","ipa":"/baɪ/","gloss":"comprar"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"}]'::jsonb, NULL, NULL)
