INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a2-m5-01', 'lesson-sequence-a2-m5', 1, 'sentence', 'What are you going to do this weekend?', 'O que você vai fazer neste fim de semana?', '/wʌt ɑːr juː ˈɡoʊɪŋ tuː duː ðɪs ˈwiːkɛnd/', 'Use going to para plano, presente contínuo para compromisso combinado e will para uma decisão ou oferta no momento. As frases trazem o contexto necessário para interpretar a escolha.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"going","pos":"verb","ipa":"/ˈɡoʊɪŋ/","gloss":"indo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"weekend","pos":"noun","ipa":"/ˈwiːkɛnd/","gloss":"fim de semana"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m5-02', 'lesson-sequence-a2-m5', 2, 'sentence', 'I''m going to visit my parents.', 'Vou visitar meus pais.', '/aɪm ˈɡoʊɪŋ tuː ˈvɪzɪt maɪ ˈpɛrənts/', 'Use going to para plano, presente contínuo para compromisso combinado e will para uma decisão ou oferta no momento. As frases trazem o contexto necessário para interpretar a escolha.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"going","pos":"verb","ipa":"/ˈɡoʊɪŋ/","gloss":"indo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"visit","pos":"noun","ipa":"/ˈvɪzɪt/","gloss":"visita"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"parents","pos":"noun","ipa":"/ˈpɛrənts/","gloss":"pais (pai e mãe)"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m5-03', 'lesson-sequence-a2-m5', 3, 'sentence', 'We''re meeting them at six on Saturday.', 'Vamos encontrá-los às seis no sábado.', '/wɪr ˈmiːtɪŋ ðɛm æt sɪks ɑːn ˈsætərdeɪ/', 'Use going to para plano, presente contínuo para compromisso combinado e will para uma decisão ou oferta no momento. As frases trazem o contexto necessário para interpretar a escolha.', '[]'::jsonb, '[{"surface":"We''re","pos":"pronoun","ipa":"/wɪr/","gloss":"nós estamos"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"them","pos":"pronoun","ipa":"/ðɛm/","gloss":"eles, os"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"six","pos":"numeral","ipa":"/sɪks/","gloss":"seis"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Saturday","pos":"proper noun","ipa":"/ˈsætərdeɪ/","gloss":"sábado"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m5-04', 'lesson-sequence-a2-m5', 4, 'sentence', 'Are you taking the train?', 'Você vai de trem?', '/ɑːr juː ˈteɪkɪŋ ðə treɪn/', 'Use going to para plano, presente contínuo para compromisso combinado e will para uma decisão ou oferta no momento. As frases trazem o contexto necessário para interpretar a escolha.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"taking","pos":"verb","ipa":"/ˈteɪkɪŋ/","gloss":"dando, pegando"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m5-05', 'lesson-sequence-a2-m5', 5, 'sentence', 'No, my brother is driving us there.', 'Não, meu irmão vai nos levar de carro.', '/noʊ maɪ ˈbrʌðər ɪz ˈdraɪvɪŋ ʌs ðɛr/', 'Use going to para plano, presente contínuo para compromisso combinado e will para uma decisão ou oferta no momento. As frases trazem o contexto necessário para interpretar a escolha.', '[]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"brother","pos":"noun","ipa":"/ˈbrʌðər/","gloss":"irmão"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"driving","pos":"verb","ipa":"/ˈdraɪvɪŋ/","gloss":"dirigindo"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m5-06', 'lesson-sequence-a2-m5', 6, 'sentence', 'I don''t have a ticket yet.', 'Ainda não tenho passagem.', '/aɪ doʊnt hæv ə ˈtɪkɪt jɛt/', 'Use going to para plano, presente contínuo para compromisso combinado e will para uma decisão ou oferta no momento. As frases trazem o contexto necessário para interpretar a escolha.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"ticket","pos":"noun","ipa":"/ˈtɪkɪt/","gloss":"passagem, bilhete"},{"surface":"yet","pos":"adverb","ipa":"/jɛt/","gloss":"ainda"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m5-07', 'lesson-sequence-a2-m5', 7, 'sentence', 'I''ll help you book one now.', 'Vou ajudar você a reservar uma agora.', '/aɪl hɛlp juː bʊk wʌn naʊ/', 'Use going to para plano, presente contínuo para compromisso combinado e will para uma decisão ou oferta no momento. As frases trazem o contexto necessário para interpretar a escolha.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"book","pos":"verb","ipa":"/bʊk/","gloss":"reservar; livro"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m5-08', 'lesson-sequence-a2-m5', 8, 'sentence', 'When does your class start tomorrow?', 'Quando começa sua aula amanhã?', '/wɛn dʌz jʊr klæs stɑːrt təˈmɑːroʊ/', 'Use going to para plano, presente contínuo para compromisso combinado e will para uma decisão ou oferta no momento. As frases trazem o contexto necessário para interpretar a escolha.', '[]'::jsonb, '[{"surface":"When","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"class","pos":"noun","ipa":"/klæs/","gloss":"aula, turma"},{"surface":"start","pos":"verb","ipa":"/stɑːrt/","gloss":"começar"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a2-ed-ing-01', 'lesson-sequence-a2-ed-ing', 1, 'sentence', 'I''m interested in this book.', 'Estou interessado neste livro.', '/aɪm ˈɪntrəstɪd ɪn ðɪs bʊk/', 'Adjetivos com -ed frequentemente descrevem como a pessoa se sente; adjetivos com -ing descrevem aquilo que provoca a sensação. Compare bored/boring e interested/interesting dentro da frase, sem aplicar a regra a todo adjetivo.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"interested","pos":"adjective","ipa":"/ˈɪntrəstɪd/","gloss":"interessado"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"book","pos":"verb","ipa":"/bʊk/","gloss":"reservar; livro"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-ed-ing-02', 'lesson-sequence-a2-ed-ing', 2, 'sentence', 'The book is interesting.', 'O livro é interessante.', '/ðə bʊk ɪz ˈɪntrəstɪŋ/', 'Adjetivos com -ed frequentemente descrevem como a pessoa se sente; adjetivos com -ing descrevem aquilo que provoca a sensação. Compare bored/boring e interested/interesting dentro da frase, sem aplicar a regra a todo adjetivo.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"book","pos":"verb","ipa":"/bʊk/","gloss":"reservar; livro"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"interesting","pos":"adjective","ipa":"/ˈɪntrəstɪŋ/","gloss":"interessante"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-ed-ing-03', 'lesson-sequence-a2-ed-ing', 3, 'sentence', 'She was bored during the film.', 'Ela ficou entediada durante o filme.', '/ʃiː wɑːz bɔːrd ˈdʊrɪŋ ðə fɪlm/', 'Adjetivos com -ed frequentemente descrevem como a pessoa se sente; adjetivos com -ing descrevem aquilo que provoca a sensação. Compare bored/boring e interested/interesting dentro da frase, sem aplicar a regra a todo adjetivo.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"bored","pos":"adjective","ipa":"/bɔːrd/","gloss":"entediado"},{"surface":"during","pos":"preposition","ipa":"/ˈdʊrɪŋ/","gloss":"durante"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"film","pos":"noun","ipa":"/fɪlm/","gloss":"filme"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-ed-ing-04', 'lesson-sequence-a2-ed-ing', 4, 'sentence', 'The film was boring.', 'O filme era entediante.', '/ðə fɪlm wɑːz ˈbɔːrɪŋ/', 'Adjetivos com -ed frequentemente descrevem como a pessoa se sente; adjetivos com -ing descrevem aquilo que provoca a sensação. Compare bored/boring e interested/interesting dentro da frase, sem aplicar a regra a todo adjetivo.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"film","pos":"noun","ipa":"/fɪlm/","gloss":"filme"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"boring","pos":"adjective","ipa":"/ˈbɔːrɪŋ/","gloss":"chato, entediante"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-ed-ing-05', 'lesson-sequence-a2-ed-ing', 5, 'sentence', 'We''re excited about the trip.', 'Estamos animados com a viagem.', '/wɪr ɪkˈsaɪtɪd əˈbaʊt ðə trɪp/', 'Adjetivos com -ed frequentemente descrevem como a pessoa se sente; adjetivos com -ing descrevem aquilo que provoca a sensação. Compare bored/boring e interested/interesting dentro da frase, sem aplicar a regra a todo adjetivo.', '[]'::jsonb, '[{"surface":"We''re","pos":"pronoun","ipa":"/wɪr/","gloss":"nós estamos"},{"surface":"excited","pos":"adjective","ipa":"/ɪkˈsaɪtɪd/","gloss":"animado, empolgado"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"trip","pos":"noun","ipa":"/trɪp/","gloss":"viagem"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-ed-ing-06', 'lesson-sequence-a2-ed-ing', 6, 'sentence', 'It''s an exciting trip.', 'É uma viagem empolgante.', '/ɪts ən ɪkˈsaɪtɪŋ trɪp/', 'Adjetivos com -ed frequentemente descrevem como a pessoa se sente; adjetivos com -ing descrevem aquilo que provoca a sensação. Compare bored/boring e interested/interesting dentro da frase, sem aplicar a regra a todo adjetivo.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"exciting","pos":"adjective","ipa":"/ɪkˈsaɪtɪŋ/","gloss":"empolgante"},{"surface":"trip","pos":"noun","ipa":"/trɪp/","gloss":"viagem"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-ed-ing-07', 'lesson-sequence-a2-ed-ing', 7, 'sentence', 'The instructions are confusing.', 'As instruções são confusas.', '/ðə ɪnˈstrʌkʃənz ɑːr kənˈfjuːzɪŋ/', 'Adjetivos com -ed frequentemente descrevem como a pessoa se sente; adjetivos com -ing descrevem aquilo que provoca a sensação. Compare bored/boring e interested/interesting dentro da frase, sem aplicar a regra a todo adjetivo.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"instructions","pos":"noun","ipa":"/ɪnˈstrʌkʃənz/","gloss":"instruções"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"confusing","pos":"adjective","ipa":"/kənˈfjuːzɪŋ/","gloss":"confuso; que causa confusão"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-ed-ing-08', 'lesson-sequence-a2-ed-ing', 8, 'sentence', 'I''m confused. Can you explain them?', 'Estou confuso. Você pode explicá-las?', '/aɪm kənˈfjuːzd kæn juː ɪkˈspleɪn ðɛm/', 'Adjetivos com -ed frequentemente descrevem como a pessoa se sente; adjetivos com -ing descrevem aquilo que provoca a sensação. Compare bored/boring e interested/interesting dentro da frase, sem aplicar a regra a todo adjetivo.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"confused","pos":"adjective","ipa":"/kənˈfjuːzd/","gloss":"confuso"},{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"explain","pos":"verb","ipa":"/ɪkˈspleɪn/","gloss":"explicar"},{"surface":"them","pos":"pronoun","ipa":"/ðɛm/","gloss":"eles, os"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a2-m6-01', 'lesson-sequence-a2-m6', 1, 'sentence', 'Do I have to arrive early?', 'Tenho que chegar cedo?', '/duː aɪ hæv tuː əˈraɪv ˈɜːrli/', 'Retome obrigação, proibição, conselho e ausência de obrigação, sem confundir don''t have to com mustn''t. Use finalidade e condição simples para explicar a escolha e sua consequência.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"arrive","pos":"verb","ipa":"/əˈraɪv/","gloss":"chegar"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m6-02', 'lesson-sequence-a2-m6', 2, 'sentence', 'No, you don''t have to come before nine.', 'Não, você não precisa vir antes das nove.', '/noʊ juː doʊnt hæv tuː kʌm bɪˈfɔːr naɪn/', 'Retome obrigação, proibição, conselho e ausência de obrigação, sem confundir don''t have to com mustn''t. Use finalidade e condição simples para explicar a escolha e sua consequência.', '[]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"nine","pos":"numeral","ipa":"/naɪn/","gloss":"nove"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m6-03', 'lesson-sequence-a2-m6', 3, 'sentence', 'You mustn''t park in front of the door.', 'Você não pode estacionar em frente à porta.', '/juː ˈmʌsənt pɑːrk ɪn frʌnt ʌv ðə dɔːr/', 'Retome obrigação, proibição, conselho e ausência de obrigação, sem confundir don''t have to com mustn''t. Use finalidade e condição simples para explicar a escolha e sua consequência.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"mustn''t","pos":"verb","ipa":"/ˈmʌsənt/","gloss":"não pode (must not)"},{"surface":"park","pos":"verb","ipa":"/pɑːrk/","gloss":"estacionar"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"front","pos":"noun","ipa":"/frʌnt/","gloss":"frente"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"door","pos":"noun","ipa":"/dɔːr/","gloss":"porta"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m6-04', 'lesson-sequence-a2-m6', 4, 'sentence', 'You should take a jacket.', 'Você deveria levar uma jaqueta.', '/juː ʃʊd teɪk ə ˈdʒækɪt/', 'Retome obrigação, proibição, conselho e ausência de obrigação, sem confundir don''t have to com mustn''t. Use finalidade e condição simples para explicar a escolha e sua consequência.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"jacket","pos":"noun","ipa":"/ˈdʒækɪt/","gloss":"jaqueta"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m6-05', 'lesson-sequence-a2-m6', 5, 'sentence', 'I want to leave early to avoid traffic.', 'Quero sair cedo para evitar o trânsito.', '/aɪ wɑːnt tuː liːv ˈɜːrli tuː əˈvɔɪd ˈtræfɪk/', 'Retome obrigação, proibição, conselho e ausência de obrigação, sem confundir don''t have to com mustn''t. Use finalidade e condição simples para explicar a escolha e sua consequência.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"want","pos":"verb","ipa":"/wɑːnt/","gloss":"querer"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"avoid","pos":"verb","ipa":"/əˈvɔɪd/","gloss":"evitar"},{"surface":"traffic","pos":"noun","ipa":"/ˈtræfɪk/","gloss":"trânsito"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m6-06', 'lesson-sequence-a2-m6', 6, 'sentence', 'If we leave now, we''ll arrive on time.', 'Se sairmos agora, chegaremos a tempo.', '/ɪf wiː liːv naʊ wiːl əˈraɪv ɑːn taɪm/', 'Retome obrigação, proibição, conselho e ausência de obrigação, sem confundir don''t have to com mustn''t. Use finalidade e condição simples para explicar a escolha e sua consequência.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"},{"surface":"we''ll","pos":"pronoun","ipa":"/wiːl/","gloss":"nós vamos (we will)"},{"surface":"arrive","pos":"verb","ipa":"/əˈraɪv/","gloss":"chegar"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m6-07', 'lesson-sequence-a2-m6', 7, 'sentence', 'I enjoy walking, but I need to take the bus today.', 'Gosto de caminhar, mas preciso pegar o ônibus hoje.', '/aɪ ɪnˈdʒɔɪ ˈwɔːkɪŋ bʌt aɪ niːd tuː teɪk ðə bʌs təˈdeɪ/', 'Retome obrigação, proibição, conselho e ausência de obrigação, sem confundir don''t have to com mustn''t. Use finalidade e condição simples para explicar a escolha e sua consequência.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"enjoy","pos":"verb","ipa":"/ɪnˈdʒɔɪ/","gloss":"aproveitar"},{"surface":"walking","pos":"noun","ipa":"/ˈwɔːkɪŋ/","gloss":"caminhada"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m6-08', 'lesson-sequence-a2-m6', 8, 'sentence', 'Could you wait here until I come back?', 'Você poderia esperar aqui até eu voltar?', '/kʊd juː weɪt hɪr ənˈtɪl aɪ kʌm bæk/', 'Retome obrigação, proibição, conselho e ausência de obrigação, sem confundir don''t have to com mustn''t. Use finalidade e condição simples para explicar a escolha e sua consequência.', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"wait","pos":"noun","ipa":"/weɪt/","gloss":"espera; esperar"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"until","pos":"conjunction","ipa":"/ənˈtɪl/","gloss":"até"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"}]'::jsonb, NULL, NULL)
