INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a2-m7-01', 'lesson-sequence-a2-m7', 1, 'sentence', 'Excuse me, I need some help.', 'Com licença, preciso de ajuda.', '/ɪkˈskjuːz miː aɪ niːd sʌm hɛlp/', 'Retome perguntas, pedidos educados, passado e vocabulário de serviços. A conversa apresenta um problema e confirma uma solução. Ler/digitar as respostas continua sendo uma prática controlada.', '[]'::jsonb, '[{"surface":"Excuse","pos":"verb","ipa":"/ɪkˈskjuːz/","gloss":"desculpar (excuse me = com licença)"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m7-02', 'lesson-sequence-a2-m7', 2, 'sentence', 'What seems to be the problem?', 'Qual parece ser o problema?', '/wʌt siːmz tuː biː ðə ˈprɑːbləm/', 'Retome perguntas, pedidos educados, passado e vocabulário de serviços. A conversa apresenta um problema e confirma uma solução. Ler/digitar as respostas continua sendo uma prática controlada.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"seems","pos":"verb","ipa":"/siːmz/","gloss":"parece"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m7-03', 'lesson-sequence-a2-m7', 3, 'sentence', 'I left my bag on the bus.', 'Deixei minha bolsa no ônibus.', '/aɪ lɛft maɪ bæɡ ɑːn ðə bʌs/', 'Retome perguntas, pedidos educados, passado e vocabulário de serviços. A conversa apresenta um problema e confirma uma solução. Ler/digitar as respostas continua sendo uma prática controlada.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m7-04', 'lesson-sequence-a2-m7', 4, 'sentence', 'What time did you take the bus?', 'A que horas você pegou o ônibus?', '/wʌt taɪm dɪd juː teɪk ðə bʌs/', 'Retome perguntas, pedidos educados, passado e vocabulário de serviços. A conversa apresenta um problema e confirma uma solução. Ler/digitar as respostas continua sendo uma prática controlada.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m7-05', 'lesson-sequence-a2-m7', 5, 'sentence', 'It was about half past eight.', 'Foi por volta das oito e meia.', '/ɪt wɑːz əˈbaʊt hæf pæst eɪt/', 'Retome perguntas, pedidos educados, passado e vocabulário de serviços. A conversa apresenta um problema e confirma uma solução. Ler/digitar as respostas continua sendo uma prática controlada.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"half","pos":"noun","ipa":"/hæf/","gloss":"metade, meio"},{"surface":"past","pos":"preposition","ipa":"/pæst/","gloss":"depois de (horas)"},{"surface":"eight","pos":"numeral","ipa":"/eɪt/","gloss":"oito"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m7-06', 'lesson-sequence-a2-m7', 6, 'sentence', 'Can you describe your bag?', 'Você pode descrever sua bolsa?', '/kæn juː dɪˈskraɪb jʊr bæɡ/', 'Retome perguntas, pedidos educados, passado e vocabulário de serviços. A conversa apresenta um problema e confirma uma solução. Ler/digitar as respostas continua sendo uma prática controlada.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"describe","pos":"verb","ipa":"/dɪˈskraɪb/","gloss":"descrever"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m7-07', 'lesson-sequence-a2-m7', 7, 'sentence', 'It''s a small black bag.', 'É uma bolsa pequena e preta.', '/ɪts ə smɔːl blæk bæɡ/', 'Retome perguntas, pedidos educados, passado e vocabulário de serviços. A conversa apresenta um problema e confirma uma solução. Ler/digitar as respostas continua sendo uma prática controlada.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"},{"surface":"black","pos":"adjective","ipa":"/blæk/","gloss":"preto"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m7-08', 'lesson-sequence-a2-m7', 8, 'sentence', 'Could you call me if you find it?', 'Você poderia me ligar se a encontrar?', '/kʊd juː kɔːl miː ɪf juː faɪnd ɪt/', 'Retome perguntas, pedidos educados, passado e vocabulário de serviços. A conversa apresenta um problema e confirma uma solução. Ler/digitar as respostas continua sendo uma prática controlada.', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"find","pos":"verb","ipa":"/faɪnd/","gloss":"encontrar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL)
