INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-a2-m8-01', 'lesson-sequence-a2-m8', 1, 'sentence', 'Have you ever visited this city?', 'Você já visitou esta cidade?', '/hæv juː ˈɛvər ˈvɪzɪtɪd ðɪs ˈsɪti/', 'Retome passado com momento definido, experiências com present perfect e planos futuros. Yesterday situa o passado; already/yet retomam resultado ou pendência no presente.', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"ever","pos":"adverb","ipa":"/ˈɛvər/","gloss":"alguma vez, já"},{"surface":"visited","pos":"verb","ipa":"/ˈvɪzɪtɪd/","gloss":"visitou"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"city","pos":"noun","ipa":"/ˈsɪti/","gloss":"cidade"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m8-02', 'lesson-sequence-a2-m8', 2, 'sentence', 'Yes, I came here last year.', 'Sim, vim aqui no ano passado.', '/jɛs aɪ keɪm hɪr læst jɪr/', 'Retome passado com momento definido, experiências com present perfect e planos futuros. Yesterday situa o passado; already/yet retomam resultado ou pendência no presente.', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"came","pos":"verb","ipa":"/keɪm/","gloss":"veio"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"year","pos":"noun","ipa":"/jɪr/","gloss":"ano"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m8-03', 'lesson-sequence-a2-m8', 3, 'sentence', 'Have you already booked a room?', 'Você já reservou um quarto?', '/hæv juː ɔːlˈrɛdi bʊkt ə ruːm/', 'Retome passado com momento definido, experiências com present perfect e planos futuros. Yesterday situa o passado; already/yet retomam resultado ou pendência no presente.', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"already","pos":"adverb","ipa":"/ɔːlˈrɛdi/","gloss":"já"},{"surface":"booked","pos":"adjective","ipa":"/bʊkt/","gloss":"reservado, lotado"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m8-04', 'lesson-sequence-a2-m8', 4, 'sentence', 'No, I haven''t booked one yet.', 'Não, ainda não reservei um.', '/noʊ aɪ ˈhævənt bʊkt wʌn jɛt/', 'Retome passado com momento definido, experiências com present perfect e planos futuros. Yesterday situa o passado; already/yet retomam resultado ou pendência no presente.', '[]'::jsonb, '[{"surface":"No","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"haven''t","pos":"verb","ipa":"/ˈhævənt/","gloss":"não (have not)"},{"surface":"booked","pos":"adjective","ipa":"/bʊkt/","gloss":"reservado, lotado"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"yet","pos":"adverb","ipa":"/jɛt/","gloss":"ainda"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m8-05', 'lesson-sequence-a2-m8', 5, 'sentence', 'I called the hotel yesterday.', 'Liguei para o hotel ontem.', '/aɪ kɔːld ðə hoʊˈtɛl ˈjɛstərdeɪ/', 'Retome passado com momento definido, experiências com present perfect e planos futuros. Yesterday situa o passado; already/yet retomam resultado ou pendência no presente.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"called","pos":"verb","ipa":"/kɔːld/","gloss":"ligou, chamou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"hotel","pos":"noun","ipa":"/hoʊˈtɛl/","gloss":"hotel"},{"surface":"yesterday","pos":"adverb","ipa":"/ˈjɛstərdeɪ/","gloss":"ontem"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m8-06', 'lesson-sequence-a2-m8', 6, 'sentence', 'They didn''t have any rooms available.', 'Eles não tinham quartos disponíveis.', '/ðeɪ ˈdɪdənt hæv ˈɛni ruːmz əˈveɪləbəl/', 'Retome passado com momento definido, experiências com present perfect e planos futuros. Yesterday situa o passado; already/yet retomam resultado ou pendência no presente.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"rooms","pos":"noun","ipa":"/ruːmz/","gloss":"quartos"},{"surface":"available","pos":"adjective","ipa":"/əˈveɪləbəl/","gloss":"disponível"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m8-07', 'lesson-sequence-a2-m8', 7, 'sentence', 'I''m going to try another hotel.', 'Vou tentar outro hotel.', '/aɪm ˈɡoʊɪŋ tuː traɪ əˈnʌðər hoʊˈtɛl/', 'Retome passado com momento definido, experiências com present perfect e planos futuros. Yesterday situa o passado; already/yet retomam resultado ou pendência no presente.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"going","pos":"verb","ipa":"/ˈɡoʊɪŋ/","gloss":"indo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"try","pos":"verb","ipa":"/traɪ/","gloss":"experimentar, tentar"},{"surface":"another","pos":"determiner","ipa":"/əˈnʌðər/","gloss":"outro, mais um"},{"surface":"hotel","pos":"noun","ipa":"/hoʊˈtɛl/","gloss":"hotel"}]'::jsonb, NULL, NULL),
  ('unit-sequence-a2-m8-08', 'lesson-sequence-a2-m8', 8, 'sentence', 'If you need help, I''ll call them with you.', 'Se você precisar de ajuda, vou ligar para eles com você.', '/ɪf juː niːd hɛlp aɪl kɔːl ðɛm wɪð juː/', 'Retome passado com momento definido, experiências com present perfect e planos futuros. Yesterday situa o passado; already/yet retomam resultado ou pendência no presente.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"them","pos":"pronoun","ipa":"/ðɛm/","gloss":"eles, os"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL)
