INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b1-m1-01', 'lesson-sequence-b1-m1', 1, 'sentence', 'I''ve worked here since March.', 'Trabalho aqui desde março.', '/aɪv wɜːrkt hɪr sɪns mɑːrtʃ/', 'Contraste experiência sem momento definido, evento passado datado e duração até o presente. For indica período e since aponta o início; o contexto distingue resultado de atividade em andamento.', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"worked","pos":"verb","ipa":"/wɜːrkt/","gloss":"trabalhou"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"since","pos":"preposition","ipa":"/sɪns/","gloss":"desde"},{"surface":"March","pos":"proper noun","ipa":"/mɑːrtʃ/","gloss":"março"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m1-02', 'lesson-sequence-b1-m1', 2, 'sentence', 'Before that, I worked at a small store.', 'Antes disso, eu trabalhava em uma loja pequena.', '/bɪˈfɔːr ðæt aɪ wɜːrkt æt ə smɔːl stɔːr/', 'Contraste experiência sem momento definido, evento passado datado e duração até o presente. For indica período e since aponta o início; o contexto distingue resultado de atividade em andamento.', '[]'::jsonb, '[{"surface":"Before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"worked","pos":"verb","ipa":"/wɜːrkt/","gloss":"trabalhou"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"},{"surface":"store","pos":"noun","ipa":"/stɔːr/","gloss":"loja, mercado"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m1-03', 'lesson-sequence-b1-m1', 3, 'sentence', 'How long have you been studying English?', 'Há quanto tempo você estuda inglês?', '/haʊ lɔːŋ hæv juː bɪn ˈstʌdiɪŋ ˈɪŋɡlɪʃ/', 'Contraste experiência sem momento definido, evento passado datado e duração até o presente. For indica período e since aponta o início; o contexto distingue resultado de atividade em andamento.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"long","pos":"adjective","ipa":"/lɔːŋ/","gloss":"longo, muito (tempo)"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"studying","pos":"verb","ipa":"/ˈstʌdiɪŋ/","gloss":"estudando"},{"surface":"English","pos":"proper noun","ipa":"/ˈɪŋɡlɪʃ/","gloss":"inglês"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m1-04', 'lesson-sequence-b1-m1', 4, 'sentence', 'I''ve been studying for two years.', 'Estudo há dois anos.', '/aɪv bɪn ˈstʌdiɪŋ fɔːr tuː jɪrz/', 'Contraste experiência sem momento definido, evento passado datado e duração até o presente. For indica período e since aponta o início; o contexto distingue resultado de atividade em andamento.', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"studying","pos":"verb","ipa":"/ˈstʌdiɪŋ/","gloss":"estudando"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m1-05', 'lesson-sequence-b1-m1', 5, 'sentence', 'Have you finished the report yet?', 'Você já terminou o relatório?', '/hæv juː ˈfɪnɪʃt ðə rɪˈpɔːrt jɛt/', 'Contraste experiência sem momento definido, evento passado datado e duração até o presente. For indica período e since aponta o início; o contexto distingue resultado de atividade em andamento.', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"finished","pos":"verb","ipa":"/ˈfɪnɪʃt/","gloss":"terminou, terminado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"report","pos":"verb","ipa":"/rɪˈpɔːrt/","gloss":"registrar, relatar"},{"surface":"yet","pos":"adverb","ipa":"/jɛt/","gloss":"ainda"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m1-06', 'lesson-sequence-b1-m1', 6, 'sentence', 'Yes, I finished it this morning.', 'Sim, terminei esta manhã.', '/jɛs aɪ ˈfɪnɪʃt ɪt ðɪs ˈmɔːrnɪŋ/', 'Contraste experiência sem momento definido, evento passado datado e duração até o presente. For indica período e since aponta o início; o contexto distingue resultado de atividade em andamento.', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"finished","pos":"verb","ipa":"/ˈfɪnɪʃt/","gloss":"terminou, terminado"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"morning","pos":"noun","ipa":"/ˈmɔːrnɪŋ/","gloss":"manhã"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m1-07', 'lesson-sequence-b1-m1', 7, 'sentence', 'We haven''t seen each other since school.', 'Não nos vemos desde a escola.', '/wiː ˈhævənt siːn iːtʃ ˈʌðər sɪns skuːl/', 'Contraste experiência sem momento definido, evento passado datado e duração até o presente. For indica período e since aponta o início; o contexto distingue resultado de atividade em andamento.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"haven''t","pos":"verb","ipa":"/ˈhævənt/","gloss":"não (have not)"},{"surface":"seen","pos":"verb","ipa":"/siːn/","gloss":"visto"},{"surface":"each","pos":"determiner","ipa":"/iːtʃ/","gloss":"cada"},{"surface":"other","pos":"pronoun","ipa":"/ˈʌðər/","gloss":"outro"},{"surface":"since","pos":"preposition","ipa":"/sɪns/","gloss":"desde"},{"surface":"school","pos":"noun","ipa":"/skuːl/","gloss":"escola"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m1-08', 'lesson-sequence-b1-m1', 8, 'sentence', 'It has been a long time.', 'Faz muito tempo.', '/ɪt hæz bɪn ə lɔːŋ taɪm/', 'Contraste experiência sem momento definido, evento passado datado e duração até o presente. For indica período e since aponta o início; o contexto distingue resultado de atividade em andamento.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"long","pos":"adjective","ipa":"/lɔːŋ/","gloss":"longo, muito (tempo)"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL)
