INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b1-m2-01', 'lesson-sequence-b1-m2', 1, 'sentence', 'I used to take the bus to work.', 'Eu costumava ir de ônibus para o trabalho.', '/aɪ juːzd tuː teɪk ðə bʌs tuː wɜːrk/', 'Organize passado simples, ação em andamento, anterioridade com past perfect e hábito anterior com used to. A relação temporal vem dos acontecimentos descritos, não apenas de uma palavra isolada.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m2-02', 'lesson-sequence-b1-m2', 2, 'sentence', 'One morning, I was waiting at the stop when it started to rain.', 'Certa manhã, eu estava esperando no ponto quando começou a chover.', '/wʌn ˈmɔːrnɪŋ aɪ wɑːz ˈweɪtɪŋ æt ðə stɑːp wɛn ɪt ˈstɑːrtɪd tuː reɪn/', 'Organize passado simples, ação em andamento, anterioridade com past perfect e hábito anterior com used to. A relação temporal vem dos acontecimentos descritos, não apenas de uma palavra isolada.', '[]'::jsonb, '[{"surface":"One","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"morning","pos":"noun","ipa":"/ˈmɔːrnɪŋ/","gloss":"manhã"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"waiting","pos":"verb","ipa":"/ˈweɪtɪŋ/","gloss":"esperando"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"stop","pos":"verb","ipa":"/stɑːp/","gloss":"parar"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"started","pos":"verb","ipa":"/ˈstɑːrtɪd/","gloss":"começado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"rain","pos":"verb","ipa":"/reɪn/","gloss":"chover; chuva"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m2-03', 'lesson-sequence-b1-m2', 3, 'sentence', 'I realised that I had left my jacket at home.', 'Percebi que tinha deixado minha jaqueta em casa.', '/aɪ ˈrɪəlaɪzd ðæt aɪ hæd lɛft maɪ ˈdʒækɪt æt hoʊm/', 'Organize passado simples, ação em andamento, anterioridade com past perfect e hábito anterior com used to. A relação temporal vem dos acontecimentos descritos, não apenas de uma palavra isolada.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"realised","pos":"verb","ipa":"/ˈrɪəlaɪzd/","gloss":"percebeu"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"jacket","pos":"noun","ipa":"/ˈdʒækɪt/","gloss":"jaqueta"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m2-04', 'lesson-sequence-b1-m2', 4, 'sentence', 'By the time the bus arrived, I was completely wet.', 'Quando o ônibus chegou, eu estava completamente molhado.', '/baɪ ðə taɪm ðə bʌs əˈraɪvd aɪ wɑːz kəmˈpliːtli wɛt/', 'Organize passado simples, ação em andamento, anterioridade com past perfect e hábito anterior com used to. A relação temporal vem dos acontecimentos descritos, não apenas de uma palavra isolada.', '[]'::jsonb, '[{"surface":"By","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"},{"surface":"arrived","pos":"verb","ipa":"/əˈraɪvd/","gloss":"chegou"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"completely","pos":"adverb","ipa":"/kəmˈpliːtli/","gloss":"completamente"},{"surface":"wet","pos":"adjective","ipa":"/wɛt/","gloss":"molhado"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m2-05', 'lesson-sequence-b1-m2', 5, 'sentence', 'The driver stopped and helped me.', 'O motorista parou e me ajudou.', '/ðə ˈdraɪvər stɑːpt ænd hɛlpt miː/', 'Organize passado simples, ação em andamento, anterioridade com past perfect e hábito anterior com used to. A relação temporal vem dos acontecimentos descritos, não apenas de uma palavra isolada.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"driver","pos":"noun","ipa":"/ˈdraɪvər/","gloss":"motorista"},{"surface":"stopped","pos":"verb","ipa":"/stɑːpt/","gloss":"parou"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"helped","pos":"verb","ipa":"/hɛlpt/","gloss":"ajudou"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m2-06', 'lesson-sequence-b1-m2', 6, 'sentence', 'Luckily, there was an empty seat near the door.', 'Felizmente, havia um assento vazio perto da porta.', '/ˈlʌkɪli ðɛr wɑːz ən ˈɛmpti siːt nɪr ðə dɔːr/', 'Organize passado simples, ação em andamento, anterioridade com past perfect e hábito anterior com used to. A relação temporal vem dos acontecimentos descritos, não apenas de uma palavra isolada.', '[]'::jsonb, '[{"surface":"Luckily","pos":"adverb","ipa":"/ˈlʌkɪli/","gloss":"por sorte"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"empty","pos":"adjective","ipa":"/ˈɛmpti/","gloss":"vazio"},{"surface":"seat","pos":"noun","ipa":"/siːt/","gloss":"assento"},{"surface":"near","pos":"preposition","ipa":"/nɪr/","gloss":"perto de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"door","pos":"noun","ipa":"/dɔːr/","gloss":"porta"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m2-07', 'lesson-sequence-b1-m2', 7, 'sentence', 'I called my manager to explain the delay.', 'Liguei para meu gerente para explicar o atraso.', '/aɪ kɔːld maɪ ˈmænɪdʒər tuː ɪkˈspleɪn ðə dɪˈleɪ/', 'Organize passado simples, ação em andamento, anterioridade com past perfect e hábito anterior com used to. A relação temporal vem dos acontecimentos descritos, não apenas de uma palavra isolada.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"called","pos":"verb","ipa":"/kɔːld/","gloss":"ligou, chamou"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"manager","pos":"noun","ipa":"/ˈmænɪdʒər/","gloss":"gerente"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"explain","pos":"verb","ipa":"/ɪkˈspleɪn/","gloss":"explicar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"delay","pos":"noun","ipa":"/dɪˈleɪ/","gloss":"atraso"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m2-08', 'lesson-sequence-b1-m2', 8, 'sentence', 'Since then, I''ve always checked the weather before leaving.', 'Desde então, sempre verifico o tempo antes de sair.', '/sɪns ðɛn aɪv ˈɔːlweɪz tʃɛkt ðə ˈwɛðər bɪˈfɔːr ˈliːvɪŋ/', 'Organize passado simples, ação em andamento, anterioridade com past perfect e hábito anterior com used to. A relação temporal vem dos acontecimentos descritos, não apenas de uma palavra isolada.', '[]'::jsonb, '[{"surface":"Since","pos":"preposition","ipa":"/sɪns/","gloss":"desde"},{"surface":"then","pos":"adverb","ipa":"/ðɛn/","gloss":"então, depois"},{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"always","pos":"adverb","ipa":"/ˈɔːlweɪz/","gloss":"sempre"},{"surface":"checked","pos":"verb","ipa":"/tʃɛkt/","gloss":"verificou, marcou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"weather","pos":"noun","ipa":"/ˈwɛðər/","gloss":"tempo, clima"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"leaving","pos":"verb","ipa":"/ˈliːvɪŋ/","gloss":"saindo"}]'::jsonb, NULL, NULL)
