INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b1-m3-01', 'lesson-sequence-b1-m3', 1, 'sentence', 'If I work late, I usually take a taxi.', 'Se trabalho até tarde, geralmente pego um táxi.', '/ɪf aɪ wɜːrk leɪt aɪ ˈjuːʒuəli teɪk ə ˈtæksi/', 'Distinga condição habitual, possibilidade futura e hipótese com if + passado/would. Must e can''t expressam dedução; might deixa a possibilidade em aberto. Não trate toda forma passada como evento passado.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"taxi","pos":"noun","ipa":"/ˈtæksi/","gloss":"táxi"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m3-02', 'lesson-sequence-b1-m3', 2, 'sentence', 'If I finish early today, I''ll walk home.', 'Se terminar cedo hoje, vou para casa a pé.', '/ɪf aɪ ˈfɪnɪʃ ˈɜːrli təˈdeɪ aɪl wɔːk hoʊm/', 'Distinga condição habitual, possibilidade futura e hipótese com if + passado/would. Must e can''t expressam dedução; might deixa a possibilidade em aberto. Não trate toda forma passada como evento passado.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"finish","pos":"verb","ipa":"/ˈfɪnɪʃ/","gloss":"terminar"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"},{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"walk","pos":"noun","ipa":"/wɔːk/","gloss":"caminhada; andar"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m3-03', 'lesson-sequence-b1-m3', 3, 'sentence', 'If I lived closer, I would walk every day.', 'Se morasse mais perto, iria a pé todos os dias.', '/ɪf aɪ lɪvd ˈkloʊsər aɪ wʊd wɔːk ˈɛvri deɪ/', 'Distinga condição habitual, possibilidade futura e hipótese com if + passado/would. Must e can''t expressam dedução; might deixa a possibilidade em aberto. Não trate toda forma passada como evento passado.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"lived","pos":"verb","ipa":"/lɪvd/","gloss":"morou, viveu"},{"surface":"closer","pos":"adverb","ipa":"/ˈkloʊsər/","gloss":"mais perto"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"walk","pos":"noun","ipa":"/wɔːk/","gloss":"caminhada; andar"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m3-04', 'lesson-sequence-b1-m3', 4, 'sentence', 'What would you do if you missed the last train?', 'O que você faria se perdesse o último trem?', '/wʌt wʊd juː duː ɪf juː mɪst ðə læst treɪn/', 'Distinga condição habitual, possibilidade futura e hipótese com if + passado/would. Must e can''t expressam dedução; might deixa a possibilidade em aberto. Não trate toda forma passada como evento passado.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"missed","pos":"verb","ipa":"/mɪst/","gloss":"perdi"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m3-05', 'lesson-sequence-b1-m3', 5, 'sentence', 'I might call a friend.', 'Talvez eu ligasse para um amigo.', '/aɪ maɪt kɔːl ə frɛnd/', 'Distinga condição habitual, possibilidade futura e hipótese com if + passado/would. Must e can''t expressam dedução; might deixa a possibilidade em aberto. Não trate toda forma passada como evento passado.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"friend","pos":"noun","ipa":"/frɛnd/","gloss":"amigo, amiga"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m3-06', 'lesson-sequence-b1-m3', 6, 'sentence', 'She must be at home. Her car is outside.', 'Ela deve estar em casa. O carro dela está lá fora.', '/ʃiː mʌst biː æt hoʊm hɜːr kɑːr ɪz ˌaʊtˈsaɪd/', 'Distinga condição habitual, possibilidade futura e hipótese com if + passado/would. Must e can''t expressam dedução; might deixa a possibilidade em aberto. Não trate toda forma passada como evento passado.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"Her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"outside","pos":"adverb","ipa":"/ˌaʊtˈsaɪd/","gloss":"lá fora"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m3-07', 'lesson-sequence-b1-m3', 7, 'sentence', 'He can''t be at work. The office is closed.', 'Ele não pode estar no trabalho. O escritório está fechado.', '/hiː kænt biː æt wɜːrk ðə ˈɔːfɪs ɪz kloʊzd/', 'Distinga condição habitual, possibilidade futura e hipótese com if + passado/would. Must e can''t expressam dedução; might deixa a possibilidade em aberto. Não trate toda forma passada como evento passado.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"office","pos":"noun","ipa":"/ˈɔːfɪs/","gloss":"escritório, balcão"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"closed","pos":"verb","ipa":"/kloʊzd/","gloss":"fechou, fechado"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m3-08', 'lesson-sequence-b1-m3', 8, 'sentence', 'If I were you, I''d check the address first.', 'Se eu fosse você, verificaria o endereço primeiro.', '/ɪf aɪ wɜːr juː aɪd tʃɛk ðə ˈædrɛs fɜːrst/', 'Distinga condição habitual, possibilidade futura e hipótese com if + passado/would. Must e can''t expressam dedução; might deixa a possibilidade em aberto. Não trate toda forma passada como evento passado.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"I''d","pos":"pronoun","ipa":"/aɪd/","gloss":"eu (gostaria)"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"address","pos":"noun","ipa":"/ˈædrɛs/","gloss":"endereço"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b1-tags-01', 'lesson-sequence-b1-tags', 1, 'sentence', 'You''re coming tomorrow, aren''t you?', 'Você vem amanhã, não vem?', '/jʊr ˈkʌmɪŋ təˈmɑːroʊ ɑːrnt juː/', 'Uma question tag retoma o auxiliar ou be da oração principal; normalmente alterna afirmação e negativa. Sem auxiliar expresso no presente/passado simples, use do/does/did. A entoação influencia se há confirmação ou dúvida.', '[]'::jsonb, '[{"surface":"You''re","pos":"pronoun","ipa":"/jʊr/","gloss":"você está, você é"},{"surface":"coming","pos":"verb","ipa":"/ˈkʌmɪŋ/","gloss":"vindo"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"},{"surface":"aren''t","pos":"verb","ipa":"/ɑːrnt/","gloss":"não são, não estão (are not)"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-tags-02', 'lesson-sequence-b1-tags', 2, 'sentence', 'She isn''t at home, is she?', 'Ela não está em casa, está?', '/ʃiː ˈɪzənt æt hoʊm ɪz ʃiː/', 'Uma question tag retoma o auxiliar ou be da oração principal; normalmente alterna afirmação e negativa. Sem auxiliar expresso no presente/passado simples, use do/does/did. A entoação influencia se há confirmação ou dúvida.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"isn''t","pos":"auxiliary verb","ipa":"/ˈɪzənt/","gloss":"não é, não está"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-tags-03', 'lesson-sequence-b1-tags', 3, 'sentence', 'He works here, doesn''t he?', 'Ele trabalha aqui, não trabalha?', '/hiː wɜːrks hɪr ˈdʌzənt hiː/', 'Uma question tag retoma o auxiliar ou be da oração principal; normalmente alterna afirmação e negativa. Sem auxiliar expresso no presente/passado simples, use do/does/did. A entoação influencia se há confirmação ou dúvida.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"works","pos":"verb","ipa":"/wɜːrks/","gloss":"funciona, serve"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"doesn''t","pos":"verb","ipa":"/ˈdʌzənt/","gloss":"não (does not)"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-tags-04', 'lesson-sequence-b1-tags', 4, 'sentence', 'You don''t need a ticket, do you?', 'Você não precisa de ingresso, precisa?', '/juː doʊnt niːd ə ˈtɪkɪt duː juː/', 'Uma question tag retoma o auxiliar ou be da oração principal; normalmente alterna afirmação e negativa. Sem auxiliar expresso no presente/passado simples, use do/does/did. A entoação influencia se há confirmação ou dúvida.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"ticket","pos":"noun","ipa":"/ˈtɪkɪt/","gloss":"passagem, bilhete"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-tags-05', 'lesson-sequence-b1-tags', 5, 'sentence', 'They arrived early, didn''t they?', 'Eles chegaram cedo, não chegaram?', '/ðeɪ əˈraɪvd ˈɜːrli ˈdɪdənt ðeɪ/', 'Uma question tag retoma o auxiliar ou be da oração principal; normalmente alterna afirmação e negativa. Sem auxiliar expresso no presente/passado simples, use do/does/did. A entoação influencia se há confirmação ou dúvida.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"arrived","pos":"verb","ipa":"/əˈraɪvd/","gloss":"chegou"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-tags-06', 'lesson-sequence-b1-tags', 6, 'sentence', 'We can sit here, can''t we?', 'Podemos sentar aqui, não podemos?', '/wiː kæn sɪt hɪr kænt wiː/', 'Uma question tag retoma o auxiliar ou be da oração principal; normalmente alterna afirmação e negativa. Sem auxiliar expresso no presente/passado simples, use do/does/did. A entoação influencia se há confirmação ou dúvida.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"sit","pos":"verb","ipa":"/sɪt/","gloss":"sentar"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-tags-07', 'lesson-sequence-b1-tags', 7, 'sentence', 'She''s already left, hasn''t she?', 'Ela já saiu, não saiu?', '/ʃiːz ɔːlˈrɛdi lɛft ˈhæzənt ʃiː/', 'Uma question tag retoma o auxiliar ou be da oração principal; normalmente alterna afirmação e negativa. Sem auxiliar expresso no presente/passado simples, use do/does/did. A entoação influencia se há confirmação ou dúvida.', '[]'::jsonb, '[{"surface":"She''s","pos":"pronoun","ipa":"/ʃiːz/","gloss":"ela é, ela está"},{"surface":"already","pos":"adverb","ipa":"/ɔːlˈrɛdi/","gloss":"já"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"hasn''t","pos":"verb","ipa":"/ˈhæzənt/","gloss":"não (has not)"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-tags-08', 'lesson-sequence-b1-tags', 8, 'sentence', 'You haven''t seen my keys, have you?', 'Você não viu minhas chaves, viu?', '/juː ˈhævənt siːn maɪ kiːz hæv juː/', 'Uma question tag retoma o auxiliar ou be da oração principal; normalmente alterna afirmação e negativa. Sem auxiliar expresso no presente/passado simples, use do/does/did. A entoação influencia se há confirmação ou dúvida.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"haven''t","pos":"verb","ipa":"/ˈhævənt/","gloss":"não (have not)"},{"surface":"seen","pos":"verb","ipa":"/siːn/","gloss":"visto"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"keys","pos":"noun","ipa":"/kiːz/","gloss":"chaves"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b1-m4-01', 'lesson-sequence-b1-m4', 1, 'sentence', 'Is this the bus that goes to the station?', 'Este é o ônibus que vai para a estação?', '/ɪz ðɪs ðə bʌs ðæt ɡoʊz tuː ðə ˈsteɪʃən/', 'Combine relativas, perguntas indiretas e question tags. A pergunta indireta mantém ordem de afirmação dentro da oração; a relativa identifica a pessoa ou coisa relevante.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"goes","pos":"verb","ipa":"/ɡoʊz/","gloss":"vai"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"station","pos":"noun","ipa":"/ˈsteɪʃən/","gloss":"estação"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m4-02', 'lesson-sequence-b1-m4', 2, 'sentence', 'The driver who helped us works here.', 'O motorista que nos ajudou trabalha aqui.', '/ðə ˈdraɪvər huː hɛlpt ʌs wɜːrks hɪr/', 'Combine relativas, perguntas indiretas e question tags. A pergunta indireta mantém ordem de afirmação dentro da oração; a relativa identifica a pessoa ou coisa relevante.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"driver","pos":"noun","ipa":"/ˈdraɪvər/","gloss":"motorista"},{"surface":"who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"helped","pos":"verb","ipa":"/hɛlpt/","gloss":"ajudou"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"works","pos":"verb","ipa":"/wɜːrks/","gloss":"funciona, serve"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m4-03', 'lesson-sequence-b1-m4', 3, 'sentence', 'Could you tell me where the ticket office is?', 'Você poderia me dizer onde fica a bilheteria?', '/kʊd juː tɛl miː wɛr ðə ˈtɪkɪt ˈɔːfɪs ɪz/', 'Combine relativas, perguntas indiretas e question tags. A pergunta indireta mantém ordem de afirmação dentro da oração; a relativa identifica a pessoa ou coisa relevante.', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"tell","pos":"verb","ipa":"/tɛl/","gloss":"contar, dizer"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"ticket","pos":"noun","ipa":"/ˈtɪkɪt/","gloss":"passagem, bilhete"},{"surface":"office","pos":"noun","ipa":"/ˈɔːfɪs/","gloss":"escritório, balcão"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m4-04', 'lesson-sequence-b1-m4', 4, 'sentence', 'Do you know what time it opens?', 'Você sabe a que horas ela abre?', '/duː juː noʊ wʌt taɪm ɪt ˈoʊpənz/', 'Combine relativas, perguntas indiretas e question tags. A pergunta indireta mantém ordem de afirmação dentro da oração; a relativa identifica a pessoa ou coisa relevante.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"opens","pos":"verb","ipa":"/ˈoʊpənz/","gloss":"abre"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m4-05', 'lesson-sequence-b1-m4', 5, 'sentence', 'It opens at nine, doesn''t it?', 'Ela abre às nove, não abre?', '/ɪt ˈoʊpənz æt naɪn ˈdʌzənt ɪt/', 'Combine relativas, perguntas indiretas e question tags. A pergunta indireta mantém ordem de afirmação dentro da oração; a relativa identifica a pessoa ou coisa relevante.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"opens","pos":"verb","ipa":"/ˈoʊpənz/","gloss":"abre"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"nine","pos":"numeral","ipa":"/naɪn/","gloss":"nove"},{"surface":"doesn''t","pos":"verb","ipa":"/ˈdʌzənt/","gloss":"não (does not)"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m4-06', 'lesson-sequence-b1-m4', 6, 'sentence', 'You haven''t bought a ticket yet, have you?', 'Você ainda não comprou passagem, comprou?', '/juː ˈhævənt bɔːt ə ˈtɪkɪt jɛt hæv juː/', 'Combine relativas, perguntas indiretas e question tags. A pergunta indireta mantém ordem de afirmação dentro da oração; a relativa identifica a pessoa ou coisa relevante.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"haven''t","pos":"verb","ipa":"/ˈhævənt/","gloss":"não (have not)"},{"surface":"bought","pos":"verb","ipa":"/bɔːt/","gloss":"comprou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"ticket","pos":"noun","ipa":"/ˈtɪkɪt/","gloss":"passagem, bilhete"},{"surface":"yet","pos":"adverb","ipa":"/jɛt/","gloss":"ainda"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m4-07', 'lesson-sequence-b1-m4', 7, 'sentence', 'This is the place where we met last year.', 'Este é o lugar onde nos encontramos no ano passado.', '/ðɪs ɪz ðə pleɪs wɛr wiː mɛt læst jɪr/', 'Combine relativas, perguntas indiretas e question tags. A pergunta indireta mantém ordem de afirmação dentro da oração; a relativa identifica a pessoa ou coisa relevante.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"place","pos":"noun","ipa":"/pleɪs/","gloss":"lugar"},{"surface":"where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"met","pos":"verb","ipa":"/mɛt/","gloss":"conheceu, encontrou"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"year","pos":"noun","ipa":"/jɪr/","gloss":"ano"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m4-08', 'lesson-sequence-b1-m4', 8, 'sentence', 'I''m interested in the tour that starts at ten.', 'Estou interessado no passeio que começa às dez.', '/aɪm ˈɪntrəstɪd ɪn ðə tʊr ðæt stɑːrts æt tɛn/', 'Combine relativas, perguntas indiretas e question tags. A pergunta indireta mantém ordem de afirmação dentro da oração; a relativa identifica a pessoa ou coisa relevante.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"interested","pos":"adjective","ipa":"/ˈɪntrəstɪd/","gloss":"interessado"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"tour","pos":"noun","ipa":"/tʊr/","gloss":"passeio guiado"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"starts","pos":"verb","ipa":"/stɑːrts/","gloss":"começa"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"ten","pos":"numeral","ipa":"/tɛn/","gloss":"dez"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b1-m5-01', 'lesson-sequence-b1-m5', 1, 'sentence', 'The road was closed yesterday.', 'A estrada foi fechada ontem.', '/ðə roʊd wɑːz kloʊzd ˈjɛstərdeɪ/', 'Retome passiva simples e discurso indireto. A passiva muda o foco para o acontecimento; o relato mantém o sentido da mensagem e ajusta tempo e referência ao contexto passado.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"road","pos":"noun","ipa":"/roʊd/","gloss":"estrada"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"closed","pos":"verb","ipa":"/kloʊzd/","gloss":"fechou, fechado"},{"surface":"yesterday","pos":"adverb","ipa":"/ˈjɛstərdeɪ/","gloss":"ontem"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m5-02', 'lesson-sequence-b1-m5', 2, 'sentence', 'We were told to use another route.', 'Disseram-nos para usar outro caminho.', '/wiː wɜːr toʊld tuː juːz əˈnʌðər ruːt/', 'Retome passiva simples e discurso indireto. A passiva muda o foco para o acontecimento; o relato mantém o sentido da mensagem e ajusta tempo e referência ao contexto passado.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"told","pos":"verb","ipa":"/toʊld/","gloss":"contou, disse"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"use","pos":"verb","ipa":"/juːz/","gloss":"usar"},{"surface":"another","pos":"determiner","ipa":"/əˈnʌðər/","gloss":"outro, mais um"},{"surface":"route","pos":"noun","ipa":"/ruːt/","gloss":"rota, caminho"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m5-03', 'lesson-sequence-b1-m5', 3, 'sentence', 'She said that the train was late.', 'Ela disse que o trem estava atrasado.', '/ʃiː sɛd ðæt ðə treɪn wɑːz leɪt/', 'Retome passiva simples e discurso indireto. A passiva muda o foco para o acontecimento; o relato mantém o sentido da mensagem e ajusta tempo e referência ao contexto passado.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m5-04', 'lesson-sequence-b1-m5', 4, 'sentence', 'He asked where we were staying.', 'Ele perguntou onde estávamos hospedados.', '/hiː æskt wɛr wiː wɜːr ˈsteɪɪŋ/', 'Retome passiva simples e discurso indireto. A passiva muda o foco para o acontecimento; o relato mantém o sentido da mensagem e ajusta tempo e referência ao contexto passado.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"asked","pos":"verb","ipa":"/æskt/","gloss":"perguntou, pediu"},{"surface":"where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"staying","pos":"verb","ipa":"/ˈsteɪɪŋ/","gloss":"ficando, hospedado"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m5-05', 'lesson-sequence-b1-m5', 5, 'sentence', 'I told him that we had booked a hotel nearby.', 'Disse a ele que tínhamos reservado um hotel por perto.', '/aɪ toʊld hɪm ðæt wiː hæd bʊkt ə hoʊˈtɛl ˌnɪrˈbaɪ/', 'Retome passiva simples e discurso indireto. A passiva muda o foco para o acontecimento; o relato mantém o sentido da mensagem e ajusta tempo e referência ao contexto passado.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"told","pos":"verb","ipa":"/toʊld/","gloss":"contou, disse"},{"surface":"him","pos":"pronoun","ipa":"/hɪm/","gloss":"ele, o, lhe"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"booked","pos":"adjective","ipa":"/bʊkt/","gloss":"reservado, lotado"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"hotel","pos":"noun","ipa":"/hoʊˈtɛl/","gloss":"hotel"},{"surface":"nearby","pos":"adverb","ipa":"/ˌnɪrˈbaɪ/","gloss":"por perto"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m5-06', 'lesson-sequence-b1-m5', 6, 'sentence', 'The receptionist asked us to wait.', 'A recepcionista pediu que esperássemos.', '/ðə rɪˈsepʃənɪst æskt ʌs tuː weɪt/', 'Retome passiva simples e discurso indireto. A passiva muda o foco para o acontecimento; o relato mantém o sentido da mensagem e ajusta tempo e referência ao contexto passado.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"receptionist","pos":"noun","ipa":"/rɪˈsepʃənɪst/","gloss":"recepcionista"},{"surface":"asked","pos":"verb","ipa":"/æskt/","gloss":"perguntou, pediu"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"wait","pos":"noun","ipa":"/weɪt/","gloss":"espera; esperar"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m5-07', 'lesson-sequence-b1-m5', 7, 'sentence', 'Breakfast is served at seven.', 'O café da manhã é servido às sete.', '/ˈbrɛkfəst ɪz sɜːrvd æt ˈsɛvən/', 'Retome passiva simples e discurso indireto. A passiva muda o foco para o acontecimento; o relato mantém o sentido da mensagem e ajusta tempo e referência ao contexto passado.', '[]'::jsonb, '[{"surface":"Breakfast","pos":"noun","ipa":"/ˈbrɛkfəst/","gloss":"café da manhã"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"served","pos":"verb","ipa":"/sɜːrvd/","gloss":"servido"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"seven","pos":"numeral","ipa":"/ˈsɛvən/","gloss":"sete"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m5-08', 'lesson-sequence-b1-m5', 8, 'sentence', 'They said they would call us the next morning.', 'Eles disseram que nos ligariam na manhã seguinte.', '/ðeɪ sɛd ðeɪ wʊd kɔːl ʌs ðə nɛkst ˈmɔːrnɪŋ/', 'Retome passiva simples e discurso indireto. A passiva muda o foco para o acontecimento; o relato mantém o sentido da mensagem e ajusta tempo e referência ao contexto passado.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"morning","pos":"noun","ipa":"/ˈmɔːrnɪŋ/","gloss":"manhã"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b1-m6-01', 'lesson-sequence-b1-m6', 1, 'sentence', 'We had to put off the meeting because the manager was ill.', 'Tivemos que adiar a reunião porque o gerente estava doente.', '/wiː hæd tuː pʊt ɔːf ðə ˈmiːtɪŋ bɪˈkɔːz ðə ˈmænɪdʒər wɑːz ɪl/', 'Combine causa, contraste, sequência e expressões frequentes. However contrasta orações; although introduz concessão. Make/do e phrasal verbs são retomados em contextos que sustentam o sentido.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"because","pos":"conjunction","ipa":"/bɪˈkɔːz/","gloss":"porque"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"manager","pos":"noun","ipa":"/ˈmænɪdʒər/","gloss":"gerente"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"ill","pos":"adjective","ipa":"/ɪl/","gloss":"doente"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m6-02', 'lesson-sequence-b1-m6', 2, 'sentence', 'Although the delay was frustrating, everyone understood.', 'Embora o atraso fosse frustrante, todos entenderam.', '/ɔːlˈðoʊ ðə dɪˈleɪ wɑːz frʌˈstreɪtɪŋ ˈɛvriwʌn ˌʌndərˈstʊd/', 'Combine causa, contraste, sequência e expressões frequentes. However contrasta orações; although introduz concessão. Make/do e phrasal verbs são retomados em contextos que sustentam o sentido.', '[]'::jsonb, '[{"surface":"Although","pos":"conjunction","ipa":"/ɔːlˈðoʊ/","gloss":"embora"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"delay","pos":"noun","ipa":"/dɪˈleɪ/","gloss":"atraso"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"frustrating","pos":"adjective","ipa":"/frʌˈstreɪtɪŋ/","gloss":"frustrante"},{"surface":"everyone","pos":"pronoun","ipa":"/ˈɛvriwʌn/","gloss":"todo mundo, pessoal"},{"surface":"understood","pos":"verb","ipa":"/ˌʌndərˈstʊd/","gloss":"entendeu"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m6-03', 'lesson-sequence-b1-m6', 3, 'sentence', 'First, we checked the dates. Then, we made a decision.', 'Primeiro, verificamos as datas. Depois, tomamos uma decisão.', '/fɜːrst wiː tʃɛkt ðə deɪts ðɛn wiː meɪd ə dɪˈsɪʒən/', 'Combine causa, contraste, sequência e expressões frequentes. However contrasta orações; although introduz concessão. Make/do e phrasal verbs são retomados em contextos que sustentam o sentido.', '[]'::jsonb, '[{"surface":"First","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"checked","pos":"verb","ipa":"/tʃɛkt/","gloss":"verificou, marcou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"dates","pos":"noun","ipa":"/deɪts/","gloss":"datas"},{"surface":"Then","pos":"adverb","ipa":"/ðɛn/","gloss":"então, depois"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"made","pos":"verb","ipa":"/meɪd/","gloss":"fez, feito"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"decision","pos":"noun","ipa":"/dɪˈsɪʒən/","gloss":"decisão"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m6-04', 'lesson-sequence-b1-m6', 4, 'sentence', 'The new date suited most people. However, a few couldn''t come.', 'A nova data servia para a maioria. No entanto, alguns não podiam vir.', '/ðə nuː deɪt ˈsuːtɪd moʊst ˈpiːpəl haʊˈɛvər ə fjuː ˈkʊdənt kʌm/', 'Combine causa, contraste, sequência e expressões frequentes. However contrasta orações; although introduz concessão. Make/do e phrasal verbs são retomados em contextos que sustentam o sentido.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"date","pos":"noun","ipa":"/deɪt/","gloss":"data"},{"surface":"suited","pos":"verb","ipa":"/ˈsuːtɪd/","gloss":"adequou-se"},{"surface":"most","pos":"determiner","ipa":"/moʊst/","gloss":"o máximo, a maioria"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"However","pos":"adverb","ipa":"/haʊˈɛvər/","gloss":"no entanto, mesmo assim"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"few","pos":"determiner","ipa":"/fjuː/","gloss":"poucos"},{"surface":"couldn''t","pos":"verb","ipa":"/ˈkʊdənt/","gloss":"não podia (could not)"},{"surface":"come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m6-05', 'lesson-sequence-b1-m6', 5, 'sentence', 'We did our best to find another solution.', 'Fizemos o possível para encontrar outra solução.', '/wiː dɪd aʊər bɛst tuː faɪnd əˈnʌðər səˈluːʃən/', 'Combine causa, contraste, sequência e expressões frequentes. However contrasta orações; although introduz concessão. Make/do e phrasal verbs são retomados em contextos que sustentam o sentido.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"our","pos":"determiner","ipa":"/aʊər/","gloss":"nosso"},{"surface":"best","pos":"adjective","ipa":"/bɛst/","gloss":"melhor"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"find","pos":"verb","ipa":"/faɪnd/","gloss":"encontrar"},{"surface":"another","pos":"determiner","ipa":"/əˈnʌðər/","gloss":"outro, mais um"},{"surface":"solution","pos":"noun","ipa":"/səˈluːʃən/","gloss":"solução"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m6-06', 'lesson-sequence-b1-m6', 6, 'sentence', 'I looked up the information before calling them.', 'Pesquisei a informação antes de ligar para eles.', '/aɪ lʊkt ʌp ðə ˌɪnfərˈmeɪʃən bɪˈfɔːr ˈkɔːlɪŋ ðɛm/', 'Combine causa, contraste, sequência e expressões frequentes. However contrasta orações; although introduz concessão. Make/do e phrasal verbs são retomados em contextos que sustentam o sentido.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"looked","pos":"verb","ipa":"/lʊkt/","gloss":"olhou, pareceu"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"information","pos":"noun","ipa":"/ˌɪnfərˈmeɪʃən/","gloss":"informação"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"calling","pos":"verb","ipa":"/ˈkɔːlɪŋ/","gloss":"ligando"},{"surface":"them","pos":"pronoun","ipa":"/ðɛm/","gloss":"eles, os"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m6-07', 'lesson-sequence-b1-m6', 7, 'sentence', 'As a result, we were able to explain the change clearly.', 'Como resultado, conseguimos explicar a mudança com clareza.', '/æz ə rɪˈzʌlt wiː wɜːr ˈeɪbəl tuː ɪkˈspleɪn ðə tʃeɪndʒ ˈklɪəli/', 'Combine causa, contraste, sequência e expressões frequentes. However contrasta orações; although introduz concessão. Make/do e phrasal verbs são retomados em contextos que sustentam o sentido.', '[]'::jsonb, '[{"surface":"As","pos":"conjunction","ipa":"/æz/","gloss":"como"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"result","pos":"noun","ipa":"/rɪˈzʌlt/","gloss":"resultado"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"able","pos":"adjective","ipa":"/ˈeɪbəl/","gloss":"capaz"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"explain","pos":"verb","ipa":"/ɪkˈspleɪn/","gloss":"explicar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"},{"surface":"clearly","pos":"adverb","ipa":"/ˈklɪəli/","gloss":"claramente"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m6-08', 'lesson-sequence-b1-m6', 8, 'sentence', 'If anything changes, I''ll let you know.', 'Se algo mudar, aviso você.', '/ɪf ˈɛniθɪŋ ˈtʃeɪndʒɪz aɪl lɛt juː noʊ/', 'Combine causa, contraste, sequência e expressões frequentes. However contrasta orações; although introduz concessão. Make/do e phrasal verbs são retomados em contextos que sustentam o sentido.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"anything","pos":"pronoun","ipa":"/ˈɛniθɪŋ/","gloss":"algo, alguma coisa"},{"surface":"changes","pos":"noun","ipa":"/ˈtʃeɪndʒɪz/","gloss":"mudanças"},{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b1-m7-01', 'lesson-sequence-b1-m7', 1, 'sentence', 'I bought this yesterday, but it doesn''t work.', 'Comprei isto ontem, mas não funciona.', '/aɪ bɔːt ðɪs ˈjɛstərdeɪ bʌt ɪt ˈdʌzənt wɜːrk/', 'Retome opinião, pedidos, reação e negociação cotidiana em turnos conectados. As frases incluem confirmação e proposta de solução; a tarefa continua usando o formato de prática existente.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"bought","pos":"verb","ipa":"/bɔːt/","gloss":"comprou"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"yesterday","pos":"adverb","ipa":"/ˈjɛstərdeɪ/","gloss":"ontem"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"doesn''t","pos":"verb","ipa":"/ˈdʌzənt/","gloss":"não (does not)"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m7-02', 'lesson-sequence-b1-m7', 2, 'sentence', 'Could I exchange it for another one?', 'Eu poderia trocá-lo por outro?', '/kʊd aɪ ɪksˈtʃeɪndʒ ɪt fɔːr əˈnʌðər wʌn/', 'Retome opinião, pedidos, reação e negociação cotidiana em turnos conectados. As frases incluem confirmação e proposta de solução; a tarefa continua usando o formato de prática existente.', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"exchange","pos":"verb","ipa":"/ɪksˈtʃeɪndʒ/","gloss":"trocar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"another","pos":"determiner","ipa":"/əˈnʌðər/","gloss":"outro, mais um"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m7-03', 'lesson-sequence-b1-m7', 3, 'sentence', 'Have you tried charging it?', 'Você tentou carregá-lo?', '/hæv juː traɪd ˈtʃɑːdʒɪŋ ɪt/', 'Retome opinião, pedidos, reação e negociação cotidiana em turnos conectados. As frases incluem confirmação e proposta de solução; a tarefa continua usando o formato de prática existente.', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"tried","pos":"verb","ipa":"/traɪd/","gloss":"tentou, experimentou"},{"surface":"charging","pos":"verb","ipa":"/ˈtʃɑːdʒɪŋ/","gloss":"carregando; cobrando"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m7-04', 'lesson-sequence-b1-m7', 4, 'sentence', 'Yes, but that didn''t solve the problem.', 'Sim, mas isso não resolveu o problema.', '/jɛs bʌt ðæt ˈdɪdənt sɑːlv ðə ˈprɑːbləm/', 'Retome opinião, pedidos, reação e negociação cotidiana em turnos conectados. As frases incluem confirmação e proposta de solução; a tarefa continua usando o formato de prática existente.', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"solve","pos":"verb","ipa":"/sɑːlv/","gloss":"resolver"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m7-05', 'lesson-sequence-b1-m7', 5, 'sentence', 'I see what you mean.', 'Entendo o que você quer dizer.', '/aɪ siː wʌt juː miːn/', 'Retome opinião, pedidos, reação e negociação cotidiana em turnos conectados. As frases incluem confirmação e proposta de solução; a tarefa continua usando o formato de prática existente.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"see","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"mean","pos":"verb","ipa":"/miːn/","gloss":"significar, querer dizer"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m7-06', 'lesson-sequence-b1-m7', 6, 'sentence', 'In my opinion, replacing it would be the best solution.', 'Na minha opinião, substituí-lo seria a melhor solução.', '/ɪn maɪ əˈpɪnjən rɪˈpleɪsɪŋ ɪt wʊd biː ðə bɛst səˈluːʃən/', 'Retome opinião, pedidos, reação e negociação cotidiana em turnos conectados. As frases incluem confirmação e proposta de solução; a tarefa continua usando o formato de prática existente.', '[]'::jsonb, '[{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"opinion","pos":"noun","ipa":"/əˈpɪnjən/","gloss":"opinião"},{"surface":"replacing","pos":"verb","ipa":"/rɪˈpleɪsɪŋ/","gloss":"substituindo"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"best","pos":"adjective","ipa":"/bɛst/","gloss":"melhor"},{"surface":"solution","pos":"noun","ipa":"/səˈluːʃən/","gloss":"solução"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m7-07', 'lesson-sequence-b1-m7', 7, 'sentence', 'Would you mind waiting while I check?', 'Você se importaria de esperar enquanto verifico?', '/wʊd juː maɪnd ˈweɪtɪŋ waɪl aɪ tʃɛk/', 'Retome opinião, pedidos, reação e negociação cotidiana em turnos conectados. As frases incluem confirmação e proposta de solução; a tarefa continua usando o formato de prática existente.', '[]'::jsonb, '[{"surface":"Would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"mind","pos":"verb","ipa":"/maɪnd/","gloss":"se importar"},{"surface":"waiting","pos":"verb","ipa":"/ˈweɪtɪŋ/","gloss":"esperando"},{"surface":"while","pos":"noun","ipa":"/waɪl/","gloss":"tempo (a while = um tempo)"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m7-08', 'lesson-sequence-b1-m7', 8, 'sentence', 'That''s fine. Thank you for your help.', 'Tudo bem. Obrigado pela ajuda.', '/ðæts faɪn θæŋk juː fɔːr jʊr hɛlp/', 'Retome opinião, pedidos, reação e negociação cotidiana em turnos conectados. As frases incluem confirmação e proposta de solução; a tarefa continua usando o formato de prática existente.', '[]'::jsonb, '[{"surface":"That''s","pos":"pronoun","ipa":"/ðæts/","gloss":"isso é"},{"surface":"fine","pos":"adjective","ipa":"/faɪn/","gloss":"bom, tudo bem"},{"surface":"Thank","pos":"verb","ipa":"/θæŋk/","gloss":"agradecer"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b1-m8-01', 'lesson-sequence-b1-m8', 1, 'sentence', 'Last month, I took a trip with two friends.', 'No mês passado, viajei com dois amigos.', '/læst mʌnθ aɪ tʊk ə trɪp wɪð tuː frɛndz/', 'Retome os blocos do B1 numa narrativa curta: situação inicial, problema, causa, ação e resultado. Conectores e referências unem as frases, mas digitar o texto não avalia escrita livre.', '[]'::jsonb, '[{"surface":"Last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"month","pos":"noun","ipa":"/mʌnθ/","gloss":"mês"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"took","pos":"verb","ipa":"/tʊk/","gloss":"pegou, levou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"trip","pos":"noun","ipa":"/trɪp/","gloss":"viagem"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"friends","pos":"noun","ipa":"/frɛndz/","gloss":"amigos"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m8-02', 'lesson-sequence-b1-m8', 2, 'sentence', 'We had planned to leave early, but our train was cancelled.', 'Tínhamos planejado sair cedo, mas nosso trem foi cancelado.', '/wiː hæd plænd tuː liːv ˈɜːrli bʌt aʊər treɪn wɑːz ˈkænsəld/', 'Retome os blocos do B1 numa narrativa curta: situação inicial, problema, causa, ação e resultado. Conectores e referências unem as frases, mas digitar o texto não avalia escrita livre.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"planned","pos":"verb","ipa":"/plænd/","gloss":"planejou"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"our","pos":"determiner","ipa":"/aʊər/","gloss":"nosso"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"cancelled","pos":"verb","ipa":"/ˈkænsəld/","gloss":"cancelado"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m8-03', 'lesson-sequence-b1-m8', 3, 'sentence', 'The person who helped us suggested taking a bus.', 'A pessoa que nos ajudou sugeriu pegar um ônibus.', '/ðə ˈpɜːrsən huː hɛlpt ʌs səˈdʒestɪd ˈteɪkɪŋ ə bʌs/', 'Retome os blocos do B1 numa narrativa curta: situação inicial, problema, causa, ação e resultado. Conectores e referências unem as frases, mas digitar o texto não avalia escrita livre.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"person","pos":"noun","ipa":"/ˈpɜːrsən/","gloss":"pessoa"},{"surface":"who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"helped","pos":"verb","ipa":"/hɛlpt/","gloss":"ajudou"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"suggested","pos":"verb","ipa":"/səˈdʒestɪd/","gloss":"sugeriu"},{"surface":"taking","pos":"verb","ipa":"/ˈteɪkɪŋ/","gloss":"dando, pegando"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m8-04', 'lesson-sequence-b1-m8', 4, 'sentence', 'Although it took longer, we decided to follow her advice.', 'Embora demorasse mais, decidimos seguir o conselho dela.', '/ɔːlˈðoʊ ɪt tʊk ˈlɔːŋɡər wiː dɪˈsaɪdɪd tuː ˈfɑːloʊ hɜːr ədˈvaɪs/', 'Retome os blocos do B1 numa narrativa curta: situação inicial, problema, causa, ação e resultado. Conectores e referências unem as frases, mas digitar o texto não avalia escrita livre.', '[]'::jsonb, '[{"surface":"Although","pos":"conjunction","ipa":"/ɔːlˈðoʊ/","gloss":"embora"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"took","pos":"verb","ipa":"/tʊk/","gloss":"pegou, levou"},{"surface":"longer","pos":"adverb","ipa":"/ˈlɔːŋɡər/","gloss":"mais (tempo)"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"decided","pos":"verb","ipa":"/dɪˈsaɪdɪd/","gloss":"decidiu"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"follow","pos":"verb","ipa":"/ˈfɑːloʊ/","gloss":"seguir"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"advice","pos":"noun","ipa":"/ədˈvaɪs/","gloss":"conselho(s)"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m8-05', 'lesson-sequence-b1-m8', 5, 'sentence', 'While we were waiting, we called the hotel.', 'Enquanto esperávamos, ligamos para o hotel.', '/waɪl wiː wɜːr ˈweɪtɪŋ wiː kɔːld ðə hoʊˈtɛl/', 'Retome os blocos do B1 numa narrativa curta: situação inicial, problema, causa, ação e resultado. Conectores e referências unem as frases, mas digitar o texto não avalia escrita livre.', '[]'::jsonb, '[{"surface":"While","pos":"noun","ipa":"/waɪl/","gloss":"tempo (a while = um tempo)"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"waiting","pos":"verb","ipa":"/ˈweɪtɪŋ/","gloss":"esperando"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"called","pos":"verb","ipa":"/kɔːld/","gloss":"ligou, chamou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"hotel","pos":"noun","ipa":"/hoʊˈtɛl/","gloss":"hotel"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m8-06', 'lesson-sequence-b1-m8', 6, 'sentence', 'They said that arriving late wouldn''t be a problem.', 'Eles disseram que chegar tarde não seria um problema.', '/ðeɪ sɛd ðæt əˈraɪvɪŋ leɪt ˈwʊdənt biː ə ˈprɑːbləm/', 'Retome os blocos do B1 numa narrativa curta: situação inicial, problema, causa, ação e resultado. Conectores e referências unem as frases, mas digitar o texto não avalia escrita livre.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"arriving","pos":"verb","ipa":"/əˈraɪvɪŋ/","gloss":"chegando"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"},{"surface":"wouldn''t","pos":"verb","ipa":"/ˈwʊdənt/","gloss":"não faria (would not)"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m8-07', 'lesson-sequence-b1-m8', 7, 'sentence', 'In the end, we arrived safely and enjoyed the trip.', 'No fim, chegamos em segurança e aproveitamos a viagem.', '/ɪn ðə ɛnd wiː əˈraɪvd ˈseɪfli ænd ɪnˈdʒɔɪd ðə trɪp/', 'Retome os blocos do B1 numa narrativa curta: situação inicial, problema, causa, ação e resultado. Conectores e referências unem as frases, mas digitar o texto não avalia escrita livre.', '[]'::jsonb, '[{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"end","pos":"noun","ipa":"/ɛnd/","gloss":"fim, final"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"arrived","pos":"verb","ipa":"/əˈraɪvd/","gloss":"chegou"},{"surface":"safely","pos":"adverb","ipa":"/ˈseɪfli/","gloss":"em segurança"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"enjoyed","pos":"verb","ipa":"/ɪnˈdʒɔɪd/","gloss":"gostou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"trip","pos":"noun","ipa":"/trɪp/","gloss":"viagem"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b1-m8-08', 'lesson-sequence-b1-m8', 8, 'sentence', 'If it happened again, I would check the transport options first.', 'Se isso acontecesse de novo, verificaria primeiro as opções de transporte.', '/ɪf ɪt ˈhæpənd əˈɡɛn aɪ wʊd tʃɛk ðə ˈtrænspɔːrt ˈɑːpʃənz fɜːrst/', 'Retome os blocos do B1 numa narrativa curta: situação inicial, problema, causa, ação e resultado. Conectores e referências unem as frases, mas digitar o texto não avalia escrita livre.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"happened","pos":"verb","ipa":"/ˈhæpənd/","gloss":"aconteceu"},{"surface":"again","pos":"adverb","ipa":"/əˈɡɛn/","gloss":"de novo"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"transport","pos":"noun","ipa":"/ˈtrænspɔːrt/","gloss":"transporte"},{"surface":"options","pos":"noun","ipa":"/ˈɑːpʃənz/","gloss":"opções"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"}]'::jsonb, NULL, NULL)
