INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b2-m1-01', 'lesson-sequence-b2-m1', 1, 'sentence', 'She must have left early; her desk is empty.', 'Ela deve ter saído cedo; a mesa dela está vazia.', '/ʃiː mʌst hæv lɛft ˈɜːrli hɜːr dɛsk ɪz ˈɛmpti/', 'Retome modais perfeitos para deduzir o passado e futuro contínuo/perfeito para atividade ou resultado futuro. O contexto explicita a evidência ou o limite temporal de cada conclusão.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"desk","pos":"noun","ipa":"/dɛsk/","gloss":"escrivaninha"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"empty","pos":"adjective","ipa":"/ˈɛmpti/","gloss":"vazio"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m1-02', 'lesson-sequence-b2-m1', 2, 'sentence', 'He can''t have read the report because he asked about the main conclusion.', 'Ele não pode ter lido o relatório porque perguntou sobre a conclusão principal.', '/hiː kænt hæv riːd ðə rɪˈpɔːrt bɪˈkɔːz hiː æskt əˈbaʊt ðə meɪn kənˈkluːʒən/', 'Retome modais perfeitos para deduzir o passado e futuro contínuo/perfeito para atividade ou resultado futuro. O contexto explicita a evidência ou o limite temporal de cada conclusão.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"read","pos":"verb","ipa":"/riːd/","gloss":"ler"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"report","pos":"verb","ipa":"/rɪˈpɔːrt/","gloss":"registrar, relatar"},{"surface":"because","pos":"conjunction","ipa":"/bɪˈkɔːz/","gloss":"porque"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"asked","pos":"verb","ipa":"/æskt/","gloss":"perguntou, pediu"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"main","pos":"adjective","ipa":"/meɪn/","gloss":"principal"},{"surface":"conclusion","pos":"noun","ipa":"/kənˈkluːʒən/","gloss":"conclusão"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m1-03', 'lesson-sequence-b2-m1', 3, 'sentence', 'They might have misunderstood the message.', 'Talvez eles tenham entendido mal a mensagem.', '/ðeɪ maɪt hæv ˌmɪsʌndərˈstʊd ðə ˈmɛsɪdʒ/', 'Retome modais perfeitos para deduzir o passado e futuro contínuo/perfeito para atividade ou resultado futuro. O contexto explicita a evidência ou o limite temporal de cada conclusão.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"misunderstood","pos":"verb","ipa":"/ˌmɪsʌndərˈstʊd/","gloss":"entendeu mal"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"message","pos":"noun","ipa":"/ˈmɛsɪdʒ/","gloss":"mensagem"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m1-04', 'lesson-sequence-b2-m1', 4, 'sentence', 'We should have checked the details before sending it.', 'Deveríamos ter conferido os detalhes antes de enviá-la.', '/wiː ʃʊd hæv tʃɛkt ðə ˈdiːteɪlz bɪˈfɔːr ˈsendɪŋ ɪt/', 'Retome modais perfeitos para deduzir o passado e futuro contínuo/perfeito para atividade ou resultado futuro. O contexto explicita a evidência ou o limite temporal de cada conclusão.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"checked","pos":"verb","ipa":"/tʃɛkt/","gloss":"verificou, marcou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"details","pos":"noun","ipa":"/ˈdiːteɪlz/","gloss":"detalhes"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"sending","pos":"verb","ipa":"/ˈsendɪŋ/","gloss":"enviando"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m1-05', 'lesson-sequence-b2-m1', 5, 'sentence', 'This time tomorrow, we''ll be discussing the results.', 'A esta hora amanhã, estaremos discutindo os resultados.', '/ðɪs taɪm təˈmɑːroʊ wiːl biː dɪˈskʌsɪŋ ðə rɪˈzʌlts/', 'Retome modais perfeitos para deduzir o passado e futuro contínuo/perfeito para atividade ou resultado futuro. O contexto explicita a evidência ou o limite temporal de cada conclusão.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"},{"surface":"we''ll","pos":"pronoun","ipa":"/wiːl/","gloss":"nós vamos (we will)"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"discussing","pos":"verb","ipa":"/dɪˈskʌsɪŋ/","gloss":"discutindo, conversando sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"results","pos":"noun","ipa":"/rɪˈzʌlts/","gloss":"resultados"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m1-06', 'lesson-sequence-b2-m1', 6, 'sentence', 'By then, I''ll have finished the summary.', 'Até lá, terei terminado o resumo.', '/baɪ ðɛn aɪl hæv ˈfɪnɪʃt ðə ˈsʌməri/', 'Retome modais perfeitos para deduzir o passado e futuro contínuo/perfeito para atividade ou resultado futuro. O contexto explicita a evidência ou o limite temporal de cada conclusão.', '[]'::jsonb, '[{"surface":"By","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"then","pos":"adverb","ipa":"/ðɛn/","gloss":"então, depois"},{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"finished","pos":"verb","ipa":"/ˈfɪnɪʃt/","gloss":"terminou, terminado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"summary","pos":"noun","ipa":"/ˈsʌməri/","gloss":"resumo"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m1-07', 'lesson-sequence-b2-m1', 7, 'sentence', 'I''m used to working under pressure.', 'Estou acostumado a trabalhar sob pressão.', '/aɪm juːzd tuː ˈwɜːrkɪŋ ˈʌndər ˈprɛʃər/', 'Retome modais perfeitos para deduzir o passado e futuro contínuo/perfeito para atividade ou resultado futuro. O contexto explicita a evidência ou o limite temporal de cada conclusão.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"under","pos":"preposition","ipa":"/ˈʌndər/","gloss":"no nome de, sob"},{"surface":"pressure","pos":"noun","ipa":"/ˈprɛʃər/","gloss":"pressão"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m1-08', 'lesson-sequence-b2-m1', 8, 'sentence', 'It took us a while to get used to the new schedule.', 'Levamos um tempo para nos acostumar ao novo horário.', '/ɪt tʊk ʌs ə waɪl tuː ɡɛt juːzd tuː ðə nuː ˈskɛdʒuːl/', 'Retome modais perfeitos para deduzir o passado e futuro contínuo/perfeito para atividade ou resultado futuro. O contexto explicita a evidência ou o limite temporal de cada conclusão.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"took","pos":"verb","ipa":"/tʊk/","gloss":"pegou, levou"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"while","pos":"noun","ipa":"/waɪl/","gloss":"tempo (a while = um tempo)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"schedule","pos":"noun","ipa":"/ˈskɛdʒuːl/","gloss":"horário, agenda"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b2-m2-01', 'lesson-sequence-b2-m2', 1, 'sentence', 'If we had left earlier, we would have caught the train.', 'Se tivéssemos saído antes, teríamos pegado o trem.', '/ɪf wiː hæd lɛft ˈɜːrliər wiː wʊd hæv kɔːt ðə treɪn/', 'Contraste condição passada irreal, relação entre passado e presente e arrependimento com wish. Unless e provided that delimitam a condição sem alterar automaticamente o tempo verbal.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"earlier","pos":"adverb","ipa":"/ˈɜːrliər/","gloss":"mais cedo, antes"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"caught","pos":"verb","ipa":"/kɔːt/","gloss":"pegou, pegado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m2-02', 'lesson-sequence-b2-m2', 2, 'sentence', 'If I had accepted that job, I would be living abroad now.', 'Se tivesse aceitado aquele emprego, estaria morando no exterior agora.', '/ɪf aɪ hæd əkˈsɛptɪd ðæt dʒɑːb aɪ wʊd biː ˈlɪvɪŋ əˈbrɔːd naʊ/', 'Contraste condição passada irreal, relação entre passado e presente e arrependimento com wish. Unless e provided that delimitam a condição sem alterar automaticamente o tempo verbal.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"accepted","pos":"verb","ipa":"/əkˈsɛptɪd/","gloss":"aceito"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"living","pos":"adjective","ipa":"/ˈlɪvɪŋ/","gloss":"de estar"},{"surface":"abroad","pos":"adverb","ipa":"/əˈbrɔːd/","gloss":"no exterior"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m2-03', 'lesson-sequence-b2-m2', 3, 'sentence', 'I wish I had asked more questions.', 'Gostaria de ter feito mais perguntas.', '/aɪ wɪʃ aɪ hæd æskt mɔːr ˈkwɛstʃənz/', 'Contraste condição passada irreal, relação entre passado e presente e arrependimento com wish. Unless e provided that delimitam a condição sem alterar automaticamente o tempo verbal.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wish","pos":"verb","ipa":"/wɪʃ/","gloss":"desejar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"asked","pos":"verb","ipa":"/æskt/","gloss":"perguntou, pediu"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"questions","pos":"noun","ipa":"/ˈkwɛstʃənz/","gloss":"perguntas, dúvidas"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m2-04', 'lesson-sequence-b2-m2', 4, 'sentence', 'If only we had checked the address.', 'Se ao menos tivéssemos verificado o endereço.', '/ɪf ˈoʊnli wiː hæd tʃɛkt ðə ˈædrɛs/', 'Contraste condição passada irreal, relação entre passado e presente e arrependimento com wish. Unless e provided that delimitam a condição sem alterar automaticamente o tempo verbal.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"only","pos":"adverb","ipa":"/ˈoʊnli/","gloss":"só, apenas"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"checked","pos":"verb","ipa":"/tʃɛkt/","gloss":"verificou, marcou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"address","pos":"noun","ipa":"/ˈædrɛs/","gloss":"endereço"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m2-05', 'lesson-sequence-b2-m2', 5, 'sentence', 'Unless the price changes, we''ll accept the offer.', 'A menos que o preço mude, aceitaremos a oferta.', '/ənˈlɛs ðə praɪs ˈtʃeɪndʒɪz wiːl əkˈsɛpt ðə ˈɔːfər/', 'Contraste condição passada irreal, relação entre passado e presente e arrependimento com wish. Unless e provided that delimitam a condição sem alterar automaticamente o tempo verbal.', '[]'::jsonb, '[{"surface":"Unless","pos":"conjunction","ipa":"/ənˈlɛs/","gloss":"a menos que"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"price","pos":"noun","ipa":"/praɪs/","gloss":"preço"},{"surface":"changes","pos":"noun","ipa":"/ˈtʃeɪndʒɪz/","gloss":"mudanças"},{"surface":"we''ll","pos":"pronoun","ipa":"/wiːl/","gloss":"nós vamos (we will)"},{"surface":"accept","pos":"verb","ipa":"/əkˈsɛpt/","gloss":"aceitar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"offer","pos":"noun","ipa":"/ˈɔːfər/","gloss":"oferta"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m2-06', 'lesson-sequence-b2-m2', 6, 'sentence', 'We can continue provided that everyone agrees.', 'Podemos continuar desde que todos concordem.', '/wiː kæn kənˈtɪnjuː prəˈvaɪdɪd ðæt ˈɛvriwʌn əˈɡriːz/', 'Contraste condição passada irreal, relação entre passado e presente e arrependimento com wish. Unless e provided that delimitam a condição sem alterar automaticamente o tempo verbal.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"continue","pos":"verb","ipa":"/kənˈtɪnjuː/","gloss":"continuar"},{"surface":"provided","pos":"conjunction","ipa":"/prəˈvaɪdɪd/","gloss":"desde que"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"everyone","pos":"pronoun","ipa":"/ˈɛvriwʌn/","gloss":"todo mundo, pessoal"},{"surface":"agrees","pos":"verb","ipa":"/əˈɡriːz/","gloss":"concorda"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m2-07', 'lesson-sequence-b2-m2', 7, 'sentence', 'If I were more organised, I wouldn''t have forgotten the meeting.', 'Se eu fosse mais organizado, não teria esquecido a reunião.', '/ɪf aɪ wɜːr mɔːr ˈɔːɡənaɪzd aɪ ˈwʊdənt hæv fərˈɡɑːtən ðə ˈmiːtɪŋ/', 'Contraste condição passada irreal, relação entre passado e presente e arrependimento com wish. Unless e provided that delimitam a condição sem alterar automaticamente o tempo verbal.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"organised","pos":"adjective","ipa":"/ˈɔːɡənaɪzd/","gloss":"organizou; organizado"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wouldn''t","pos":"verb","ipa":"/ˈwʊdənt/","gloss":"não faria (would not)"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"forgotten","pos":"verb","ipa":"/fərˈɡɑːtən/","gloss":"esquecido"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m2-08', 'lesson-sequence-b2-m2', 8, 'sentence', 'I wish the neighbours would stop making so much noise.', 'Gostaria que os vizinhos parassem de fazer tanto barulho.', '/aɪ wɪʃ ðə ˈneɪbəz wʊd stɑːp ˈmeɪkɪŋ soʊ mʌtʃ nɔɪz/', 'Contraste condição passada irreal, relação entre passado e presente e arrependimento com wish. Unless e provided that delimitam a condição sem alterar automaticamente o tempo verbal.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wish","pos":"verb","ipa":"/wɪʃ/","gloss":"desejar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"neighbours","pos":"noun","ipa":"/ˈneɪbəz/","gloss":"vizinhos"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"stop","pos":"verb","ipa":"/stɑːp/","gloss":"parar"},{"surface":"making","pos":"verb","ipa":"/ˈmeɪkɪŋ/","gloss":"fazendo"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"noise","pos":"noun","ipa":"/nɔɪz/","gloss":"barulho"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b2-m3-01', 'lesson-sequence-b2-m3', 1, 'sentence', 'The equipment is being checked at the moment.', 'O equipamento está sendo verificado neste momento.', '/ðə ɪˈkwɪpmənt ɪz ˈbiːɪŋ tʃɛkt æt ðə ˈmoʊmənt/', 'Retome passivas em tempos diferentes e have/get + objeto + particípio. No causativo, alguém faz o serviço para o sujeito; isso difere de o sujeito realizar a ação diretamente.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"equipment","pos":"noun","ipa":"/ɪˈkwɪpmənt/","gloss":"equipamento"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"being","pos":"verb","ipa":"/ˈbiːɪŋ/","gloss":"sendo"},{"surface":"checked","pos":"verb","ipa":"/tʃɛkt/","gloss":"verificou, marcou"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"moment","pos":"noun","ipa":"/ˈmoʊmənt/","gloss":"momento"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m3-02', 'lesson-sequence-b2-m3', 2, 'sentence', 'The problem had been reported before the meeting.', 'O problema havia sido comunicado antes da reunião.', '/ðə ˈprɑːbləm hæd bɪn rɪˈpɔːrtɪd bɪˈfɔːr ðə ˈmiːtɪŋ/', 'Retome passivas em tempos diferentes e have/get + objeto + particípio. No causativo, alguém faz o serviço para o sujeito; isso difere de o sujeito realizar a ação diretamente.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"reported","pos":"verb","ipa":"/rɪˈpɔːrtɪd/","gloss":"relatado"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m3-03', 'lesson-sequence-b2-m3', 3, 'sentence', 'The results will be published next week.', 'Os resultados serão publicados na próxima semana.', '/ðə rɪˈzʌlts wɪl biː ˈpʌblɪʃt nɛkst wiːk/', 'Retome passivas em tempos diferentes e have/get + objeto + particípio. No causativo, alguém faz o serviço para o sujeito; isso difere de o sujeito realizar a ação diretamente.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"results","pos":"noun","ipa":"/rɪˈzʌlts/","gloss":"resultados"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"published","pos":"verb","ipa":"/ˈpʌblɪʃt/","gloss":"publicado"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m3-04', 'lesson-sequence-b2-m3', 4, 'sentence', 'The documents should have been sent yesterday.', 'Os documentos deveriam ter sido enviados ontem.', '/ðə ˈdɑːkjəmənts ʃʊd hæv bɪn sɛnt ˈjɛstərdeɪ/', 'Retome passivas em tempos diferentes e have/get + objeto + particípio. No causativo, alguém faz o serviço para o sujeito; isso difere de o sujeito realizar a ação diretamente.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"documents","pos":"noun","ipa":"/ˈdɑːkjəmənts/","gloss":"documentos"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"sent","pos":"verb","ipa":"/sɛnt/","gloss":"enviou"},{"surface":"yesterday","pos":"adverb","ipa":"/ˈjɛstərdeɪ/","gloss":"ontem"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m3-05', 'lesson-sequence-b2-m3', 5, 'sentence', 'I had my phone repaired last week.', 'Mandei consertar meu telefone na semana passada.', '/aɪ hæd maɪ foʊn rɪˈpɛrd læst wiːk/', 'Retome passivas em tempos diferentes e have/get + objeto + particípio. No causativo, alguém faz o serviço para o sujeito; isso difere de o sujeito realizar a ação diretamente.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"repaired","pos":"verb","ipa":"/rɪˈpɛrd/","gloss":"consertado"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m3-06', 'lesson-sequence-b2-m3', 6, 'sentence', 'We''re getting the windows cleaned tomorrow.', 'Vamos mandar limpar as janelas amanhã.', '/wɪr ˈɡɛtɪŋ ðə ˈwɪndəʊz kliːnd təˈmɑːroʊ/', 'Retome passivas em tempos diferentes e have/get + objeto + particípio. No causativo, alguém faz o serviço para o sujeito; isso difere de o sujeito realizar a ação diretamente.', '[]'::jsonb, '[{"surface":"We''re","pos":"pronoun","ipa":"/wɪr/","gloss":"nós estamos"},{"surface":"getting","pos":"verb","ipa":"/ˈɡɛtɪŋ/","gloss":"ficando; getting up = levantar-se"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"windows","pos":"noun","ipa":"/ˈwɪndəʊz/","gloss":"janelas"},{"surface":"cleaned","pos":"verb","ipa":"/kliːnd/","gloss":"limpo"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m3-07', 'lesson-sequence-b2-m3', 7, 'sentence', 'Has the date been confirmed yet?', 'A data já foi confirmada?', '/hæz ðə deɪt bɪn kənˈfɜːrmd jɛt/', 'Retome passivas em tempos diferentes e have/get + objeto + particípio. No causativo, alguém faz o serviço para o sujeito; isso difere de o sujeito realizar a ação diretamente.', '[]'::jsonb, '[{"surface":"Has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"date","pos":"noun","ipa":"/deɪt/","gloss":"data"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"confirmed","pos":"verb","ipa":"/kənˈfɜːrmd/","gloss":"confirmado"},{"surface":"yet","pos":"adverb","ipa":"/jɛt/","gloss":"ainda"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m3-08', 'lesson-sequence-b2-m3', 8, 'sentence', 'The room must be cleaned before the guests arrive.', 'O quarto deve ser limpo antes de os hóspedes chegarem.', '/ðə ruːm mʌst biː kliːnd bɪˈfɔːr ðə ɡɛsts əˈraɪv/', 'Retome passivas em tempos diferentes e have/get + objeto + particípio. No causativo, alguém faz o serviço para o sujeito; isso difere de o sujeito realizar a ação diretamente.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"cleaned","pos":"verb","ipa":"/kliːnd/","gloss":"limpo"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"guests","pos":"noun","ipa":"/ɡɛsts/","gloss":"convidados"},{"surface":"arrive","pos":"verb","ipa":"/əˈraɪv/","gloss":"chegar"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b2-m4-01', 'lesson-sequence-b2-m4', 1, 'sentence', 'My sister, who lives abroad, is visiting next week.', 'Minha irmã, que mora no exterior, vem nos visitar na próxima semana.', '/maɪ ˈsɪstər huː lɪvz əˈbrɔːd ɪz ˈvɪzɪtɪŋ nɛkst wiːk/', 'Retome relativas explicativas e a mudança de sentido de remember/stop com infinitivo ou -ing. O contexto torna explícita a diferença entre recordar uma ação e lembrar de executá-la.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"sister","pos":"noun","ipa":"/ˈsɪstər/","gloss":"irmã"},{"surface":"who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"lives","pos":"verb","ipa":"/lɪvz/","gloss":"mora, vive"},{"surface":"abroad","pos":"adverb","ipa":"/əˈbrɔːd/","gloss":"no exterior"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"visiting","pos":"adjective","ipa":"/ˈvɪzɪtɪŋ/","gloss":"de visita"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m4-02', 'lesson-sequence-b2-m4', 2, 'sentence', 'The report, which was published yesterday, contains new evidence.', 'O relatório, que foi publicado ontem, contém novas evidências.', '/ðə rɪˈpɔːrt wɪtʃ wɑːz ˈpʌblɪʃt ˈjɛstərdeɪ kənˈteɪnz nuː ˈɛvɪdəns/', 'Retome relativas explicativas e a mudança de sentido de remember/stop com infinitivo ou -ing. O contexto torna explícita a diferença entre recordar uma ação e lembrar de executá-la.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"report","pos":"verb","ipa":"/rɪˈpɔːrt/","gloss":"registrar, relatar"},{"surface":"which","pos":"determiner","ipa":"/wɪtʃ/","gloss":"qual"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"published","pos":"verb","ipa":"/ˈpʌblɪʃt/","gloss":"publicado"},{"surface":"yesterday","pos":"adverb","ipa":"/ˈjɛstərdeɪ/","gloss":"ontem"},{"surface":"contains","pos":"verb","ipa":"/kənˈteɪnz/","gloss":"contém"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"evidence","pos":"noun","ipa":"/ˈɛvɪdəns/","gloss":"evidência"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m4-03', 'lesson-sequence-b2-m4', 3, 'sentence', 'I remember meeting her at the conference.', 'Lembro-me de tê-la conhecido na conferência.', '/aɪ rɪˈmɛmbər ˈmiːtɪŋ hɜːr æt ðə ˈkɒnfərəns/', 'Retome relativas explicativas e a mudança de sentido de remember/stop com infinitivo ou -ing. O contexto torna explícita a diferença entre recordar uma ação e lembrar de executá-la.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"remember","pos":"verb","ipa":"/rɪˈmɛmbər/","gloss":"lembrar"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"conference","pos":"noun","ipa":"/ˈkɒnfərəns/","gloss":"conferência"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m4-04', 'lesson-sequence-b2-m4', 4, 'sentence', 'Please remember to send her the invitation.', 'Por favor, lembre-se de enviar o convite para ela.', '/pliːz rɪˈmɛmbər tuː sɛnd hɜːr ðə ˌɪnvɪˈteɪʃən/', 'Retome relativas explicativas e a mudança de sentido de remember/stop com infinitivo ou -ing. O contexto torna explícita a diferença entre recordar uma ação e lembrar de executá-la.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"remember","pos":"verb","ipa":"/rɪˈmɛmbər/","gloss":"lembrar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"send","pos":"verb","ipa":"/sɛnd/","gloss":"enviar, mandar"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"invitation","pos":"noun","ipa":"/ˌɪnvɪˈteɪʃən/","gloss":"convite"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m4-05', 'lesson-sequence-b2-m4', 5, 'sentence', 'He stopped working because he was exhausted.', 'Ele parou de trabalhar porque estava exausto.', '/hiː stɑːpt ˈwɜːrkɪŋ bɪˈkɔːz hiː wɑːz ɪɡˈzɔːstɪd/', 'Retome relativas explicativas e a mudança de sentido de remember/stop com infinitivo ou -ing. O contexto torna explícita a diferença entre recordar uma ação e lembrar de executá-la.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"stopped","pos":"verb","ipa":"/stɑːpt/","gloss":"parou"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"because","pos":"conjunction","ipa":"/bɪˈkɔːz/","gloss":"porque"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"exhausted","pos":"adjective","ipa":"/ɪɡˈzɔːstɪd/","gloss":"exausto"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m4-06', 'lesson-sequence-b2-m4', 6, 'sentence', 'On the way home, he stopped to buy some food.', 'No caminho para casa, ele parou para comprar comida.', '/ɑːn ðə weɪ hoʊm hiː stɑːpt tuː baɪ sʌm fuːd/', 'Retome relativas explicativas e a mudança de sentido de remember/stop com infinitivo ou -ing. O contexto torna explícita a diferença entre recordar uma ação e lembrar de executá-la.', '[]'::jsonb, '[{"surface":"On","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"way","pos":"noun","ipa":"/weɪ/","gloss":"caminho; jeito"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"stopped","pos":"verb","ipa":"/stɑːpt/","gloss":"parou"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"buy","pos":"verb","ipa":"/baɪ/","gloss":"comprar"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"food","pos":"noun","ipa":"/fuːd/","gloss":"comida"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m4-07', 'lesson-sequence-b2-m4', 7, 'sentence', 'The person whose bag was lost has contacted us.', 'A pessoa cuja bolsa foi perdida entrou em contato conosco.', '/ðə ˈpɜːrsən huːz bæɡ wɑːz lɔːst hæz ˈkɑːntæktɪd ʌs/', 'Retome relativas explicativas e a mudança de sentido de remember/stop com infinitivo ou -ing. O contexto torna explícita a diferença entre recordar uma ação e lembrar de executá-la.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"person","pos":"noun","ipa":"/ˈpɜːrsən/","gloss":"pessoa"},{"surface":"whose","pos":"pronoun","ipa":"/huːz/","gloss":"de quem"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"lost","pos":"adjective","ipa":"/lɔːst/","gloss":"perdido; perdeu"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"contacted","pos":"verb","ipa":"/ˈkɑːntæktɪd/","gloss":"entrou em contato"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m4-08', 'lesson-sequence-b2-m4', 8, 'sentence', 'We regret to inform you that the event has been cancelled.', 'Lamentamos informar que o evento foi cancelado.', '/wiː rɪˈɡrɛt tuː ɪnˈfɔːrm juː ðæt ðə ɪˈvent hæz bɪn ˈkænsəld/', 'Retome relativas explicativas e a mudança de sentido de remember/stop com infinitivo ou -ing. O contexto torna explícita a diferença entre recordar uma ação e lembrar de executá-la.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"regret","pos":"verb","ipa":"/rɪˈɡrɛt/","gloss":"lamentar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"inform","pos":"verb","ipa":"/ɪnˈfɔːrm/","gloss":"informar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"event","pos":"noun","ipa":"/ɪˈvent/","gloss":"evento"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"cancelled","pos":"verb","ipa":"/ˈkænsəld/","gloss":"cancelado"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b2-m5-01', 'lesson-sequence-b2-m5', 1, 'sentence', 'Education matters, but the education she received was very limited.', 'A educação importa, mas a educação que ela recebeu foi muito limitada.', '/ˌɛdʒuˈkeɪʃən ˈmætərz bʌt ðə ˌɛdʒuˈkeɪʃən ʃiː rɪˈsiːvd wɑːz ˈvɛri ˈlɪmɪtɪd/', 'Retome artigos, intensidade e colocações para especificar referências e ligar ideias. Diferencie referência geral e específica; escolha a intensidade pelo adjetivo e mantenha as retomadas claras.', '[]'::jsonb, '[{"surface":"Education","pos":"noun","ipa":"/ˌɛdʒuˈkeɪʃən/","gloss":"educação"},{"surface":"matters","pos":"verb","ipa":"/ˈmætərz/","gloss":"importa"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"education","pos":"noun","ipa":"/ˌɛdʒuˈkeɪʃən/","gloss":"educação"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"received","pos":"verb","ipa":"/rɪˈsiːvd/","gloss":"recebeu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"very","pos":"adverb","ipa":"/ˈvɛri/","gloss":"muito"},{"surface":"limited","pos":"adjective","ipa":"/ˈlɪmɪtɪd/","gloss":"limitado"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m5-02', 'lesson-sequence-b2-m5', 2, 'sentence', 'The first proposal was fairly practical.', 'A primeira proposta era razoavelmente prática.', '/ðə fɜːrst prəˈpoʊzəl wɑːz ˈfɛrli ˈpræktɪkəl/', 'Retome artigos, intensidade e colocações para especificar referências e ligar ideias. Diferencie referência geral e específica; escolha a intensidade pelo adjetivo e mantenha as retomadas claras.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"proposal","pos":"noun","ipa":"/prəˈpoʊzəl/","gloss":"proposta"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"fairly","pos":"adverb","ipa":"/ˈfɛrli/","gloss":"bastante, razoavelmente"},{"surface":"practical","pos":"adjective","ipa":"/ˈpræktɪkəl/","gloss":"prático"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m5-03', 'lesson-sequence-b2-m5', 3, 'sentence', 'The second was considerably more expensive.', 'A segunda era consideravelmente mais cara.', '/ðə ˈsɛkənd wɑːz kənˈsɪdərəbli mɔːr ɪkˈspɛnsɪv/', 'Retome artigos, intensidade e colocações para especificar referências e ligar ideias. Diferencie referência geral e específica; escolha a intensidade pelo adjetivo e mantenha as retomadas claras.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"second","pos":"adjective","ipa":"/ˈsɛkənd/","gloss":"segundo"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"considerably","pos":"adverb","ipa":"/kənˈsɪdərəbli/","gloss":"consideravelmente"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"expensive","pos":"adjective","ipa":"/ɪkˈspɛnsɪv/","gloss":"caro"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m5-04', 'lesson-sequence-b2-m5', 4, 'sentence', 'We were absolutely exhausted after the discussion.', 'Estávamos completamente exaustos depois da discussão.', '/wiː wɜːr ˌæbsəˈluːtli ɪɡˈzɔːstɪd ˈæftər ðə dɪˈskʌʃən/', 'Retome artigos, intensidade e colocações para especificar referências e ligar ideias. Diferencie referência geral e específica; escolha a intensidade pelo adjetivo e mantenha as retomadas claras.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"absolutely","pos":"adverb","ipa":"/ˌæbsəˈluːtli/","gloss":"absolutamente"},{"surface":"exhausted","pos":"adjective","ipa":"/ɪɡˈzɔːstɪd/","gloss":"exausto"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"discussion","pos":"noun","ipa":"/dɪˈskʌʃən/","gloss":"discussão"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m5-05', 'lesson-sequence-b2-m5', 5, 'sentence', 'Despite the cost, the plan attracted considerable attention.', 'Apesar do custo, o plano atraiu bastante atenção.', '/dɪˈspaɪt ðə kɔːst ðə plæn əˈtræktɪd kənˈsɪdərəbəl əˈtɛnʃən/', 'Retome artigos, intensidade e colocações para especificar referências e ligar ideias. Diferencie referência geral e específica; escolha a intensidade pelo adjetivo e mantenha as retomadas claras.', '[]'::jsonb, '[{"surface":"Despite","pos":"preposition","ipa":"/dɪˈspaɪt/","gloss":"apesar de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"cost","pos":"verb","ipa":"/kɔːst/","gloss":"custar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"plan","pos":"noun","ipa":"/plæn/","gloss":"plano"},{"surface":"attracted","pos":"verb","ipa":"/əˈtræktɪd/","gloss":"atraiu"},{"surface":"considerable","pos":"adjective","ipa":"/kənˈsɪdərəbəl/","gloss":"considerável"},{"surface":"attention","pos":"noun","ipa":"/əˈtɛnʃən/","gloss":"atenção"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m5-06', 'lesson-sequence-b2-m5', 6, 'sentence', 'However, it raised serious concerns about safety.', 'No entanto, ele gerou sérias preocupações sobre a segurança.', '/haʊˈɛvər ɪt reɪzd ˈsɪriəs kənˈsɜːrnz əˈbaʊt ˈseɪfti/', 'Retome artigos, intensidade e colocações para especificar referências e ligar ideias. Diferencie referência geral e específica; escolha a intensidade pelo adjetivo e mantenha as retomadas claras.', '[]'::jsonb, '[{"surface":"However","pos":"adverb","ipa":"/haʊˈɛvər/","gloss":"no entanto, mesmo assim"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"raised","pos":"verb","ipa":"/reɪzd/","gloss":"levantou; aumentou"},{"surface":"serious","pos":"adjective","ipa":"/ˈsɪriəs/","gloss":"sério"},{"surface":"concerns","pos":"noun","ipa":"/kənˈsɜːrnz/","gloss":"preocupações"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"safety","pos":"noun","ipa":"/ˈseɪfti/","gloss":"segurança"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m5-07', 'lesson-sequence-b2-m5', 7, 'sentence', 'We need to take these concerns into account.', 'Precisamos levar essas preocupações em consideração.', '/wiː niːd tuː teɪk ðiːz kənˈsɜːrnz ˈɪntuː əˈkaʊnt/', 'Retome artigos, intensidade e colocações para especificar referências e ligar ideias. Diferencie referência geral e específica; escolha a intensidade pelo adjetivo e mantenha as retomadas claras.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"these","pos":"determiner","ipa":"/ðiːz/","gloss":"estes, estas"},{"surface":"concerns","pos":"noun","ipa":"/kənˈsɜːrnz/","gloss":"preocupações"},{"surface":"into","pos":"preposition","ipa":"/ˈɪntuː/","gloss":"para dentro de"},{"surface":"account","pos":"noun","ipa":"/əˈkaʊnt/","gloss":"conta (cadastro)"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m5-08', 'lesson-sequence-b2-m5', 8, 'sentence', 'Clear communication would help us reach an agreement.', 'Uma comunicação clara nos ajudaria a chegar a um acordo.', '/klɪr kəˌmjuːnɪˈkeɪʃən wʊd hɛlp ʌs riːtʃ ən əˈɡriːmənt/', 'Retome artigos, intensidade e colocações para especificar referências e ligar ideias. Diferencie referência geral e específica; escolha a intensidade pelo adjetivo e mantenha as retomadas claras.', '[]'::jsonb, '[{"surface":"Clear","pos":"adjective","ipa":"/klɪr/","gloss":"claro"},{"surface":"communication","pos":"noun","ipa":"/kəˌmjuːnɪˈkeɪʃən/","gloss":"comunicação"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"reach","pos":"verb","ipa":"/riːtʃ/","gloss":"alcançar, chegar a"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"agreement","pos":"noun","ipa":"/əˈɡriːmənt/","gloss":"acordo"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b2-m6-01', 'lesson-sequence-b2-m6', 1, 'sentence', 'I would argue that flexible schedules can improve working conditions.', 'Eu defenderia que horários flexíveis podem melhorar as condições de trabalho.', '/aɪ wʊd ˈɑːrɡjuː ðæt ˈflɛksəbəl ˈskɛdʒuːlz kæn ɪmˈpruːv ˈwɜːrkɪŋ kənˈdɪʃənz/', 'Organize posição, razão, exemplo, contraponto e conclusão, retomando concessão e avaliação de evidências. As frases formam um argumento-modelo, sem substituir a produção de um argumento próprio.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"argue","pos":"verb","ipa":"/ˈɑːrɡjuː/","gloss":"defender, sustentar"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"flexible","pos":"adjective","ipa":"/ˈflɛksəbəl/","gloss":"flexível"},{"surface":"schedules","pos":"noun","ipa":"/ˈskɛdʒuːlz/","gloss":"horários"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"improve","pos":"verb","ipa":"/ɪmˈpruːv/","gloss":"melhorar"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"conditions","pos":"noun","ipa":"/kənˈdɪʃənz/","gloss":"condições"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m6-02', 'lesson-sequence-b2-m6', 2, 'sentence', 'One advantage is that people can organise their time more effectively.', 'Uma vantagem é que as pessoas podem organizar seu tempo de maneira mais eficaz.', '/wʌn ədˈvæntɪdʒ ɪz ðæt ˈpiːpəl kæn ˈɔːɡənaɪz ðɛr taɪm mɔːr ɪˈfektɪvli/', 'Organize posição, razão, exemplo, contraponto e conclusão, retomando concessão e avaliação de evidências. As frases formam um argumento-modelo, sem substituir a produção de um argumento próprio.', '[]'::jsonb, '[{"surface":"One","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"advantage","pos":"noun","ipa":"/ədˈvæntɪdʒ/","gloss":"vantagem"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"organise","pos":"verb","ipa":"/ˈɔːɡənaɪz/","gloss":"organizar"},{"surface":"their","pos":"determiner","ipa":"/ðɛr/","gloss":"deles, delas"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"effectively","pos":"adverb","ipa":"/ɪˈfektɪvli/","gloss":"de forma eficaz"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m6-03', 'lesson-sequence-b2-m6', 3, 'sentence', 'For instance, they may be able to avoid travelling at busy times.', 'Por exemplo, elas podem conseguir evitar deslocamentos nos horários de maior movimento.', '/fɔːr ˈɪnstəns ðeɪ meɪ biː ˈeɪbəl tuː əˈvɔɪd ˈtrævəlɪŋ æt ˈbɪzi taɪmz/', 'Organize posição, razão, exemplo, contraponto e conclusão, retomando concessão e avaliação de evidências. As frases formam um argumento-modelo, sem substituir a produção de um argumento próprio.', '[]'::jsonb, '[{"surface":"For","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"instance","pos":"noun","ipa":"/ˈɪnstəns/","gloss":"exemplo, caso"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"may","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"able","pos":"adjective","ipa":"/ˈeɪbəl/","gloss":"capaz"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"avoid","pos":"verb","ipa":"/əˈvɔɪd/","gloss":"evitar"},{"surface":"travelling","pos":"verb","ipa":"/ˈtrævəlɪŋ/","gloss":"viajando"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"busy","pos":"adjective","ipa":"/ˈbɪzi/","gloss":"ocupado"},{"surface":"times","pos":"noun","ipa":"/taɪmz/","gloss":"vezes"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m6-04', 'lesson-sequence-b2-m6', 4, 'sentence', 'Nevertheless, flexibility alone does not solve every problem.', 'Ainda assim, a flexibilidade por si só não resolve todos os problemas.', '/ˌnɛvərðəˈlɛs ˌflɛksəˈbɪləti əˈloʊn dʌz nɑːt sɑːlv ˈɛvri ˈprɑːbləm/', 'Organize posição, razão, exemplo, contraponto e conclusão, retomando concessão e avaliação de evidências. As frases formam um argumento-modelo, sem substituir a produção de um argumento próprio.', '[]'::jsonb, '[{"surface":"Nevertheless","pos":"adverb","ipa":"/ˌnɛvərðəˈlɛs/","gloss":"no entanto"},{"surface":"flexibility","pos":"noun","ipa":"/ˌflɛksəˈbɪləti/","gloss":"flexibilidade"},{"surface":"alone","pos":"adverb","ipa":"/əˈloʊn/","gloss":"sozinho"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"solve","pos":"verb","ipa":"/sɑːlv/","gloss":"resolver"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m6-05', 'lesson-sequence-b2-m6', 5, 'sentence', 'Some argue that it makes communication more difficult.', 'Alguns argumentam que ela dificulta a comunicação.', '/sʌm ˈɑːrɡjuː ðæt ɪt meɪks kəˌmjuːnɪˈkeɪʃən mɔːr ˈdɪfɪkəlt/', 'Organize posição, razão, exemplo, contraponto e conclusão, retomando concessão e avaliação de evidências. As frases formam um argumento-modelo, sem substituir a produção de um argumento próprio.', '[]'::jsonb, '[{"surface":"Some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"argue","pos":"verb","ipa":"/ˈɑːrɡjuː/","gloss":"defender, sustentar"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"makes","pos":"verb","ipa":"/meɪks/","gloss":"faz"},{"surface":"communication","pos":"noun","ipa":"/kəˌmjuːnɪˈkeɪʃən/","gloss":"comunicação"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"difficult","pos":"adjective","ipa":"/ˈdɪfɪkəlt/","gloss":"difícil"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m6-06', 'lesson-sequence-b2-m6', 6, 'sentence', 'While that concern is reasonable, clear agreements can reduce the risk.', 'Embora essa preocupação seja razoável, acordos claros podem reduzir o risco.', '/waɪl ðæt kənˈsɜːrn ɪz ˈriːzənəbəl klɪr əˈɡriːmənts kæn rɪˈduːs ðə rɪsk/', 'Organize posição, razão, exemplo, contraponto e conclusão, retomando concessão e avaliação de evidências. As frases formam um argumento-modelo, sem substituir a produção de um argumento próprio.', '[]'::jsonb, '[{"surface":"While","pos":"noun","ipa":"/waɪl/","gloss":"tempo (a while = um tempo)"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"concern","pos":"noun","ipa":"/kənˈsɜːrn/","gloss":"preocupação"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"reasonable","pos":"adjective","ipa":"/ˈriːzənəbəl/","gloss":"razoável"},{"surface":"clear","pos":"adjective","ipa":"/klɪr/","gloss":"claro"},{"surface":"agreements","pos":"noun","ipa":"/əˈɡriːmənts/","gloss":"acordos"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"reduce","pos":"verb","ipa":"/rɪˈduːs/","gloss":"reduzir"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"risk","pos":"noun","ipa":"/rɪsk/","gloss":"risco"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m6-07', 'lesson-sequence-b2-m6', 7, 'sentence', 'The available evidence should be considered before making a decision.', 'As evidências disponíveis devem ser consideradas antes de tomar uma decisão.', '/ðə əˈveɪləbəl ˈɛvɪdəns ʃʊd biː kənˈsɪdərd bɪˈfɔːr ˈmeɪkɪŋ ə dɪˈsɪʒən/', 'Organize posição, razão, exemplo, contraponto e conclusão, retomando concessão e avaliação de evidências. As frases formam um argumento-modelo, sem substituir a produção de um argumento próprio.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"available","pos":"adjective","ipa":"/əˈveɪləbəl/","gloss":"disponível"},{"surface":"evidence","pos":"noun","ipa":"/ˈɛvɪdəns/","gloss":"evidência"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"considered","pos":"verb","ipa":"/kənˈsɪdərd/","gloss":"considerou"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"making","pos":"verb","ipa":"/ˈmeɪkɪŋ/","gloss":"fazendo"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"decision","pos":"noun","ipa":"/dɪˈsɪʒən/","gloss":"decisão"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m6-08', 'lesson-sequence-b2-m6', 8, 'sentence', 'On balance, the approach is worth trying, provided that its effects are reviewed.', 'Considerando tudo, vale a pena experimentar a abordagem, desde que seus efeitos sejam avaliados.', '/ɑːn ˈbæləns ðə əˈproʊtʃ ɪz wɜːrθ ˈtraɪɪŋ prəˈvaɪdɪd ðæt ɪts ɪˈfɛkts ɑːr rɪˈvjuːd/', 'Organize posição, razão, exemplo, contraponto e conclusão, retomando concessão e avaliação de evidências. As frases formam um argumento-modelo, sem substituir a produção de um argumento próprio.', '[]'::jsonb, '[{"surface":"On","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"balance","pos":"noun","ipa":"/ˈbæləns/","gloss":"equilíbrio, saldo"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"approach","pos":"noun","ipa":"/əˈproʊtʃ/","gloss":"abordagem"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"worth","pos":"adjective","ipa":"/wɜːrθ/","gloss":"que vale a pena"},{"surface":"trying","pos":"verb","ipa":"/ˈtraɪɪŋ/","gloss":"tentando"},{"surface":"provided","pos":"conjunction","ipa":"/prəˈvaɪdɪd/","gloss":"desde que"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"its","pos":"determiner","ipa":"/ɪts/","gloss":"seu, sua (de coisa)"},{"surface":"effects","pos":"noun","ipa":"/ɪˈfɛkts/","gloss":"efeitos"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"reviewed","pos":"verb","ipa":"/rɪˈvjuːd/","gloss":"revisada"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b2-m7-01', 'lesson-sequence-b2-m7', 1, 'sentence', 'Would it be possible to move the meeting to Thursday?', 'Seria possível mudar a reunião para quinta-feira?', '/wʊd ɪt biː ˈpɑːsəbəl tuː muːv ðə ˈmiːtɪŋ tuː ˈθɜːrzdeɪ/', 'Retome pedidos indiretos, recusa e discordância com educação. O contexto informa a intenção; expressões de suavização não significam concordância automática e variam conforme a relação entre interlocutores.', '[]'::jsonb, '[{"surface":"Would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"possible","pos":"adjective","ipa":"/ˈpɑːsəbəl/","gloss":"possível"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"move","pos":"verb","ipa":"/muːv/","gloss":"mover, passar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"Thursday","pos":"proper noun","ipa":"/ˈθɜːrzdeɪ/","gloss":"quinta-feira"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m7-02', 'lesson-sequence-b2-m7', 2, 'sentence', 'I''m afraid Thursday wouldn''t work for me.', 'Infelizmente, quinta-feira não serviria para mim.', '/aɪm əˈfreɪd ˈθɜːrzdeɪ ˈwʊdənt wɜːrk fɔːr miː/', 'Retome pedidos indiretos, recusa e discordância com educação. O contexto informa a intenção; expressões de suavização não significam concordância automática e variam conforme a relação entre interlocutores.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"afraid","pos":"adjective","ipa":"/əˈfreɪd/","gloss":"com medo"},{"surface":"Thursday","pos":"proper noun","ipa":"/ˈθɜːrzdeɪ/","gloss":"quinta-feira"},{"surface":"wouldn''t","pos":"verb","ipa":"/ˈwʊdənt/","gloss":"não faria (would not)"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m7-03', 'lesson-sequence-b2-m7', 3, 'sentence', 'Could we consider Friday instead?', 'Poderíamos considerar sexta-feira em vez disso?', '/kʊd wiː kənˈsɪdər ˈfraɪdeɪ ɪnˈstɛd/', 'Retome pedidos indiretos, recusa e discordância com educação. O contexto informa a intenção; expressões de suavização não significam concordância automática e variam conforme a relação entre interlocutores.', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"consider","pos":"verb","ipa":"/kənˈsɪdər/","gloss":"considerar"},{"surface":"Friday","pos":"proper noun","ipa":"/ˈfraɪdeɪ/","gloss":"sexta-feira"},{"surface":"instead","pos":"adverb","ipa":"/ɪnˈstɛd/","gloss":"em vez disso"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m7-04', 'lesson-sequence-b2-m7', 4, 'sentence', 'I see your point, but I have a different concern.', 'Entendo seu ponto de vista, mas tenho outra preocupação.', '/aɪ siː jʊr pɔɪnt bʌt aɪ hæv ə ˈdɪfərənt kənˈsɜːrn/', 'Retome pedidos indiretos, recusa e discordância com educação. O contexto informa a intenção; expressões de suavização não significam concordância automática e variam conforme a relação entre interlocutores.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"see","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"point","pos":"noun","ipa":"/pɔɪnt/","gloss":"ponto, argumento"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"different","pos":"adjective","ipa":"/ˈdɪfərənt/","gloss":"diferente"},{"surface":"concern","pos":"noun","ipa":"/kənˈsɜːrn/","gloss":"preocupação"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m7-05', 'lesson-sequence-b2-m7', 5, 'sentence', 'I''d rather check the details before agreeing.', 'Eu preferiria verificar os detalhes antes de concordar.', '/aɪd ˈræðər tʃɛk ðə ˈdiːteɪlz bɪˈfɔːr əˈɡriːɪŋ/', 'Retome pedidos indiretos, recusa e discordância com educação. O contexto informa a intenção; expressões de suavização não significam concordância automática e variam conforme a relação entre interlocutores.', '[]'::jsonb, '[{"surface":"I''d","pos":"pronoun","ipa":"/aɪd/","gloss":"eu (gostaria)"},{"surface":"rather","pos":"adverb","ipa":"/ˈræðər/","gloss":"de preferência"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"details","pos":"noun","ipa":"/ˈdiːteɪlz/","gloss":"detalhes"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"agreeing","pos":"verb","ipa":"/əˈɡriːɪŋ/","gloss":"concordando"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m7-06', 'lesson-sequence-b2-m7', 6, 'sentence', 'That sounds reasonable. Shall we discuss it tomorrow?', 'Isso parece razoável. Vamos discutir isso amanhã?', '/ðæt saʊndz ˈriːzənəbəl ʃæl wiː dɪˈskʌs ɪt təˈmɑːroʊ/', 'Retome pedidos indiretos, recusa e discordância com educação. O contexto informa a intenção; expressões de suavização não significam concordância automática e variam conforme a relação entre interlocutores.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"sounds","pos":"verb","ipa":"/saʊndz/","gloss":"soa, parece"},{"surface":"reasonable","pos":"adjective","ipa":"/ˈriːzənəbəl/","gloss":"razoável"},{"surface":"Shall","pos":"verb","ipa":"/ʃæl/","gloss":"auxiliar para proposta ou futuro"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"discuss","pos":"verb","ipa":"/dɪˈskʌs/","gloss":"discutir; conversar sobre"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m7-07', 'lesson-sequence-b2-m7', 7, 'sentence', 'I didn''t mean to cause any confusion.', 'Não tive a intenção de causar confusão.', '/aɪ ˈdɪdənt miːn tuː kɔːz ˈɛni kənˈfjuːʒən/', 'Retome pedidos indiretos, recusa e discordância com educação. O contexto informa a intenção; expressões de suavização não significam concordância automática e variam conforme a relação entre interlocutores.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"mean","pos":"verb","ipa":"/miːn/","gloss":"significar, querer dizer"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"cause","pos":"verb","ipa":"/kɔːz/","gloss":"causar"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"confusion","pos":"noun","ipa":"/kənˈfjuːʒən/","gloss":"confusão"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m7-08', 'lesson-sequence-b2-m7', 8, 'sentence', 'Thank you for clarifying what you meant.', 'Obrigado por esclarecer o que você quis dizer.', '/θæŋk juː fɔːr ˈklærɪfaɪɪŋ wʌt juː mɛnt/', 'Retome pedidos indiretos, recusa e discordância com educação. O contexto informa a intenção; expressões de suavização não significam concordância automática e variam conforme a relação entre interlocutores.', '[]'::jsonb, '[{"surface":"Thank","pos":"verb","ipa":"/θæŋk/","gloss":"agradecer"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"clarifying","pos":"verb","ipa":"/ˈklærɪfaɪɪŋ/","gloss":"esclarecendo"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"meant","pos":"verb","ipa":"/mɛnt/","gloss":"quis dizer, significou"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-sequence-b2-m8-01', 'lesson-sequence-b2-m8', 1, 'sentence', 'A new transport plan has been proposed for the city.', 'Um novo plano de transporte foi proposto para a cidade.', '/ə nuː ˈtrænspɔːrt plæn hæz bɪn prəˈpoʊzd fɔːr ðə ˈsɪti/', 'Integre especulação, passiva, condição, coesão e argumentação em um tema social. O texto delimita evidência e incerteza. A conclusão trata do material praticado, não certifica o domínio integral do B2.', '[]'::jsonb, '[{"surface":"A","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"transport","pos":"noun","ipa":"/ˈtrænspɔːrt/","gloss":"transporte"},{"surface":"plan","pos":"noun","ipa":"/plæn/","gloss":"plano"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"proposed","pos":"verb","ipa":"/prəˈpoʊzd/","gloss":"propôs"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"city","pos":"noun","ipa":"/ˈsɪti/","gloss":"cidade"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m8-02', 'lesson-sequence-b2-m8', 2, 'sentence', 'It could reduce traffic, provided that enough people use it.', 'Ele poderia reduzir o trânsito, desde que um número suficiente de pessoas o utilizasse.', '/ɪt kʊd rɪˈduːs ˈtræfɪk prəˈvaɪdɪd ðæt ɪˈnʌf ˈpiːpəl juːz ɪt/', 'Integre especulação, passiva, condição, coesão e argumentação em um tema social. O texto delimita evidência e incerteza. A conclusão trata do material praticado, não certifica o domínio integral do B2.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"reduce","pos":"verb","ipa":"/rɪˈduːs/","gloss":"reduzir"},{"surface":"traffic","pos":"noun","ipa":"/ˈtræfɪk/","gloss":"trânsito"},{"surface":"provided","pos":"conjunction","ipa":"/prəˈvaɪdɪd/","gloss":"desde que"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"enough","pos":"adverb","ipa":"/ɪˈnʌf/","gloss":"o bastante"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"use","pos":"verb","ipa":"/juːz/","gloss":"usar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m8-03', 'lesson-sequence-b2-m8', 3, 'sentence', 'Supporters argue that it would also improve air quality.', 'Os defensores argumentam que ele também melhoraria a qualidade do ar.', '/səˈpɔːtəz ˈɑːrɡjuː ðæt ɪt wʊd ˈɔːlsoʊ ɪmˈpruːv ɛr ˈkwɑːləti/', 'Integre especulação, passiva, condição, coesão e argumentação em um tema social. O texto delimita evidência e incerteza. A conclusão trata do material praticado, não certifica o domínio integral do B2.', '[]'::jsonb, '[{"surface":"Supporters","pos":"noun","ipa":"/səˈpɔːtəz/","gloss":"apoiadores"},{"surface":"argue","pos":"verb","ipa":"/ˈɑːrɡjuː/","gloss":"defender, sustentar"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"also","pos":"adverb","ipa":"/ˈɔːlsoʊ/","gloss":"também"},{"surface":"improve","pos":"verb","ipa":"/ɪmˈpruːv/","gloss":"melhorar"},{"surface":"air","pos":"noun","ipa":"/ɛr/","gloss":"ar"},{"surface":"quality","pos":"noun","ipa":"/ˈkwɑːləti/","gloss":"qualidade"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m8-04', 'lesson-sequence-b2-m8', 4, 'sentence', 'However, the cost has raised concerns among residents.', 'No entanto, o custo gerou preocupações entre os moradores.', '/haʊˈɛvər ðə kɔːst hæz reɪzd kənˈsɜːrnz əˈmʌŋ ˈrɛzɪdənts/', 'Integre especulação, passiva, condição, coesão e argumentação em um tema social. O texto delimita evidência e incerteza. A conclusão trata do material praticado, não certifica o domínio integral do B2.', '[]'::jsonb, '[{"surface":"However","pos":"adverb","ipa":"/haʊˈɛvər/","gloss":"no entanto, mesmo assim"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"cost","pos":"verb","ipa":"/kɔːst/","gloss":"custar"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"raised","pos":"verb","ipa":"/reɪzd/","gloss":"levantou; aumentou"},{"surface":"concerns","pos":"noun","ipa":"/kənˈsɜːrnz/","gloss":"preocupações"},{"surface":"among","pos":"preposition","ipa":"/əˈmʌŋ/","gloss":"entre"},{"surface":"residents","pos":"noun","ipa":"/ˈrɛzɪdənts/","gloss":"moradores"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m8-05', 'lesson-sequence-b2-m8', 5, 'sentence', 'If the earlier proposal had been accepted, work would have started last year.', 'Se a proposta anterior tivesse sido aceita, as obras teriam começado no ano passado.', '/ɪf ðə ˈɜːrliər prəˈpoʊzəl hæd bɪn əkˈsɛptɪd wɜːrk wʊd hæv ˈstɑːrtɪd læst jɪr/', 'Integre especulação, passiva, condição, coesão e argumentação em um tema social. O texto delimita evidência e incerteza. A conclusão trata do material praticado, não certifica o domínio integral do B2.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"earlier","pos":"adverb","ipa":"/ˈɜːrliər/","gloss":"mais cedo, antes"},{"surface":"proposal","pos":"noun","ipa":"/prəˈpoʊzəl/","gloss":"proposta"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"accepted","pos":"verb","ipa":"/əkˈsɛptɪd/","gloss":"aceito"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"started","pos":"verb","ipa":"/ˈstɑːrtɪd/","gloss":"começado"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"year","pos":"noun","ipa":"/jɪr/","gloss":"ano"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m8-06', 'lesson-sequence-b2-m8', 6, 'sentence', 'By the end of the month, the team will have reviewed the alternatives.', 'Até o fim do mês, a equipe terá analisado as alternativas.', '/baɪ ðə ɛnd ʌv ðə mʌnθ ðə tiːm wɪl hæv rɪˈvjuːd ðə ɔːlˈtɜːnətɪvz/', 'Integre especulação, passiva, condição, coesão e argumentação em um tema social. O texto delimita evidência e incerteza. A conclusão trata do material praticado, não certifica o domínio integral do B2.', '[]'::jsonb, '[{"surface":"By","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"end","pos":"noun","ipa":"/ɛnd/","gloss":"fim, final"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"month","pos":"noun","ipa":"/mʌnθ/","gloss":"mês"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"team","pos":"noun","ipa":"/tiːm/","gloss":"time, equipe"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"reviewed","pos":"verb","ipa":"/rɪˈvjuːd/","gloss":"revisada"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"alternatives","pos":"noun","ipa":"/ɔːlˈtɜːnətɪvz/","gloss":"alternativas"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m8-07', 'lesson-sequence-b2-m8', 7, 'sentence', 'More information is needed before a final decision can be made.', 'São necessárias mais informações antes que uma decisão final possa ser tomada.', '/mɔːr ˌɪnfərˈmeɪʃən ɪz ˈniːdɪd bɪˈfɔːr ə ˈfaɪnəl dɪˈsɪʒən kæn biː meɪd/', 'Integre especulação, passiva, condição, coesão e argumentação em um tema social. O texto delimita evidência e incerteza. A conclusão trata do material praticado, não certifica o domínio integral do B2.', '[]'::jsonb, '[{"surface":"More","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"information","pos":"noun","ipa":"/ˌɪnfərˈmeɪʃən/","gloss":"informação"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"needed","pos":"verb","ipa":"/ˈniːdɪd/","gloss":"precisou"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"final","pos":"adjective","ipa":"/ˈfaɪnəl/","gloss":"final, último"},{"surface":"decision","pos":"noun","ipa":"/dɪˈsɪʒən/","gloss":"decisão"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"made","pos":"verb","ipa":"/meɪd/","gloss":"fez, feito"}]'::jsonb, NULL, NULL),
  ('unit-sequence-b2-m8-08', 'lesson-sequence-b2-m8', 8, 'sentence', 'Overall, the potential benefits should be weighed against the costs.', 'De modo geral, os possíveis benefícios devem ser ponderados em relação aos custos.', '/ˌoʊvərˈɔːl ðə pəˈtɛnʃəl ˈbɛnəfɪts ʃʊd biː weɪd əˈɡɛnst ðə kɔːsts/', 'Integre especulação, passiva, condição, coesão e argumentação em um tema social. O texto delimita evidência e incerteza. A conclusão trata do material praticado, não certifica o domínio integral do B2.', '[]'::jsonb, '[{"surface":"Overall","pos":"adverb","ipa":"/ˌoʊvərˈɔːl/","gloss":"no geral"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"potential","pos":"noun","ipa":"/pəˈtɛnʃəl/","gloss":"potencial"},{"surface":"benefits","pos":"noun","ipa":"/ˈbɛnəfɪts/","gloss":"benefícios"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"weighed","pos":"verb","ipa":"/weɪd/","gloss":"pesou; ponderou"},{"surface":"against","pos":"preposition","ipa":"/əˈɡɛnst/","gloss":"contra"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"costs","pos":"verb","ipa":"/kɔːsts/","gloss":"custa"}]'::jsonb, NULL, NULL)
